#!/usr/bin/env ts-node
// Harness: the loop -- the model's first connection to the real world.
// @ts-nocheck
/**
 * s01_agent_loop.ts - The Agent Loop
 *
 * The entire secret of an AI coding agent in one pattern:
 *
 *     while stop_reason == "tool_use":
 *         response = await LLM(messages, tools)
 *         execute tools
 *         append results
 *
 *     +----------+      +-------+      +---------+
 *     |   User   | ---> |  LLM  | ---> |  Tool   |
 *     |  prompt  |      |       |      | execute |
 *     +----------+      +---+---+      +----+----+
 *                           ^               |
 *                           |   tool_result |
 *                           +---------------+
 *                           (loop continues)
 *
 * This is the core loop: feed tool results back to the model
 * until the model decides to stop. Production agents layer
 * policy, hooks, and lifecycle controls on top.
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. ASYNC/AWAIT:
 *    - Python: Uses Anthropic's sync client by default
 *    - TypeScript: Must use async/await with the SDK
 *    - All SDK calls return Promises that must be awaited
 *
 * 2. TYPE SAFETY:
 *    - Python: Dynamic typing, runtime type checking
 *    - TypeScript: Compile-time type checking with interfaces
 *    - Content blocks use discriminated unions for type safety
 *
 * 3. MODULE SYSTEM:
 *    - Python: Uses import statements
 *    - TypeScript: Uses ES modules with .js extensions (required for Node.js ESM)
 *
 * 4. ENVIRONMENT:
 *    - Python: python-dotenv for .env files
 *    - TypeScript: Same dotenv package, but with typed config
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
// TypeScript: dotenv returns an object, we destructure to get config()
config();

// TypeScript: Must check for BASE_URL and handle auth token removal
// Python: os.getenv("ANTHROPIC_BASE_URL")
if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

// Initialize Anthropic client
// TypeScript: new Anthropic() vs Python: Anthropic(base_url=...)
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});

// TypeScript: const with type assertion vs Python: simple variable
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

// TypeScript: Template literals work the same as Python f-strings
const SYSTEM = `You are a coding agent at ${process.cwd()}. Use bash to solve tasks. Act, don't explain.`;

// TypeScript: Interface for tool definition (compile-time type safety)
// Python: Dict with runtime structure only
interface BashTool {
    name: string;
    description: string;
    input_schema: {
        type: "object";
        properties: Record<string, { type: string }>;
        required: string[];
    };
}

// Define the bash tool
// TypeScript: Explicit const type vs Python's implicit dict
const TOOLS: BashTool[] = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object",
            properties: { command: { type: "string" } },
            required: ["command"],
        },
    },
];

// Promisify exec for async/await
// Python: subprocess.run is synchronous (or uses asyncio)
// TypeScript: Node.js exec is callback-based, we promisify it
const execAsync = promisify(exec);

/**
 * Run a bash command with safety checks
 *
 * TypeScript: async function returning Promise<string>
 * Python: def run_bash(command: str) -> str (synchronous)
 *
 * Key differences:
 * - TypeScript uses async/await for non-blocking execution
 * - Type annotations are compile-time (stripped at runtime)
 * - Error handling with try/catch vs Python's exception handling
 */
async function runBash(command: string): Promise<string> {
    // TypeScript: Array of readonly strings (const assertion)
    // Python: List of strings
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    // TypeScript: Array.some() with lambda
    // Python: any(d in command for d in dangerous)
    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        // TypeScript: Destructuring assignment
        // Python: r = subprocess.run(...); out = r.stdout + r.stderr
        const { stdout, stderr } = await execAsync(command, {
            cwd: process.cwd(),
            timeout: 120000, // 120 seconds in milliseconds
        });

        // TypeScript: Template literal with trim()
        // Python: (r.stdout + r.stderr).strip()
        const output = (stdout + stderr).trim();

        // TypeScript: Ternary operator
        // Python: out[:50000] if out else "(no output)"
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        // TypeScript: Type narrowing with instanceof
        // Python: except subprocess.TimeoutExpired
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * THE CORE PATTERN: Agent loop that calls tools until the model stops
 *
 * This is the heart of every AI coding agent. The loop:
 * 1. Sends messages + tools to the LLM
 * 2. Gets back response with tool_use calls
 * 3. Executes each tool, collects results
 * 4. Appends results as user message
 * 5. Loops back until model stops calling tools
 *
 * TypeScript: async function (returns Promise<void>)
 * Python: def agent_loop(messages: list) (returns None)
 *
 * Key differences:
 * - TypeScript must await all SDK calls
 * - Type-safe message handling with discriminated unions
 * - For...of loop vs Python's for block in response.content
 */
async function agentLoop(messages: Message[]): Promise<void> {
    // TypeScript: while loop with true (same as Python)
    while (true) {
        // TypeScript: await required for SDK call
        // Python: response = client.messages.create(...) (synchronous)
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        // Append assistant turn
        // TypeScript: Push to array with proper type
        // Python: messages.append({"role": "assistant", "content": response.content})
        messages.push({
            role: "assistant",
            content: response.content,
        });

        // If the model didn't call a tool, we're done
        // TypeScript: Strict equality check (=== vs ==)
        // Python: if response.stop_reason != "tool_use"
        if (response.stop_reason !== "tool_use") {
            return;
        }

        // Execute each tool call, collect results
        // TypeScript: Type annotation for array
        // Python: results = []
        const results: ToolResultBlock[] = [];

        // TypeScript: For...of loop (similar to Python's for block in...)
        for (const block of response.content) {
            // TypeScript: Type guard for discriminated union
            // Python: if block.type == "tool_use"
            if (block.type === "tool_use") {
                // TypeScript: ANSI color codes in template literal
                // Python: print(f"\033[33m$ {block.input['command']}\033[0m")
                console.log(`\x1b[33m$ ${block.input.command}\x1b[0m`);

                // TypeScript: Await async function call
                // Python: output = run_bash(block.input["command"])
                const output = await runBash(block.input.command);

                // TypeScript: String slicing
                // Python: print(output[:200])
                console.log(output.slice(0, 200));

                // TypeScript: Object with type-safe properties
                // Python: results.append({"type": "tool_result", ...})
                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        // Append tool results as user message
        // TypeScript: Type-safe message object
        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Types for message handling
 *
 * TypeScript: These interfaces define the shape of our data at compile time
 * Python: Would use dicts or TypedDict (runtime type hints only)
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    [key: string]: unknown;
}

interface ToolUseBlock extends ContentBlock {
    type: "tool_use";
    id: string;
    name: string;
    input: { command: string };
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Main REPL loop
 *
 * TypeScript: async function with readline for input
 * Python: while True with input()
 *
 * Key differences:
 * - TypeScript uses readline/promises or readline.createInterface
 * - Python's built-in input() is synchronous
 * - Error handling with try/catch vs Python's except
 */
async function main(): Promise<void> {
    // TypeScript: Array of Message objects
    // Python: history = []
    const history: Message[] = [];

    // TypeScript: Create readline interface for user input
    // Python: Uses built-in input() function
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    // TypeScript: Helper to prompt for input (promisified)
    // Python: query = input("s01 >> ")
    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 1: Agent Loop. Type 'q' to exit.\n");

    // TypeScript: while loop (same as Python)
    while (true) {
        try {
            // TypeScript: await question() for async input
            // Python: query = input("\033[36ms01 >> \033[0m")
            const query = await question("\x1b[36ms01 >> \x1b[0m");

            // TypeScript: String trimming and lowercase
            // Python: if query.strip().lower() in ("q", "exit", "")
            if (query.trim().toLowerCase() === "q" || query.trim().toLowerCase() === "exit" || query.trim() === "") {
                break;
            }

            // Append user message
            // TypeScript: Type-safe push
            // Python: history.append({"role": "user", "content": query})
            history.push({
                role: "user",
                content: query,
            });

            // Run agent loop
            // TypeScript: await required
            // Python: agent_loop(history)
            await agentLoop(history);

            // Print response content
            // TypeScript: Type narrowing
            // Python: if isinstance(response_content, list)
            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    // TypeScript: Check for text property
                    // Python: if hasattr(block, "text")
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            // TypeScript: Error handling
            // Python: except (EOFError, KeyboardInterrupt)
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    // TypeScript: Close readline interface
    rl.close();
}

// TypeScript: Run main function
// Python: if __name__ == "__main__": main()
main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: tool dispatch -- expanding what the model can reach.
// @ts-nocheck
/**
 * s02_tool_use.ts - Tools
 *
 * The agent loop from s01 didn't change. We just added tools to the array
 * and a dispatch map to route calls.
 *
 *     +----------+      +-------+      +------------------+
 *     |   User   | ---> |  LLM  | ---> | Tool Dispatch   |
 *     |  prompt  |      |       |      | {               |
 *     +----------+      +---+---+      |   bash: runBash |
 *                           |          |   read: runRead |
 *                           |          |   write: runWr  |
 *                           +----------+   edit: runEdit |
 *                           tool_result| }               |
 *                                      +------------------+
 *
 * Key insight: "The loop didn't change at all. I just added tools."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. TOOL HANDLERS MAP:
 *    - Python: TOOL_HANDLERS = {"bash": lambda **kw: run_bash(kw["command"]), ...}
 *    - TypeScript: Record<string, ToolHandler> with proper function types
 *    - Uses arrow functions with type-safe parameters
 *
 * 2. IMPORTS:
 *    - Python: from pathlib import Path
 *    - TypeScript: import path from "path" (built-in Node.js module)
 *
 * 3. TYPE SAFETY:
 *    - Python: Runtime type checking with isinstance()
 *    - TypeScript: Compile-time type checking with interfaces
 *    - Discriminated unions for content blocks
 *
 * 4. ERROR HANDLING:
 *    - Python: try/except with Exception as e
 *    - TypeScript: try/catch with error instanceof Error
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks. Act, don't explain.`;

// Promisify exec for async/await
const execAsync = promisify(exec);

/**
 * Safe path validation
 *
 * TypeScript: Returns string (absolute path)
 * Python: Returns Path object
 *
 * TypeScript uses path.resolve() and path.relative() for path operations
 * Python uses pathlib.Path with is_relative_to() method
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    // Check if path escapes working directory
    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

/**
 * Bash tool handler
 * TypeScript: async function returning Promise<string>
 * Python: def run_bash(command: str) -> str
 */
async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * File read tool handler
 * TypeScript: async function with optional limit parameter
 * Python: def run_read(path: str, limit: int = None) -> str
 */
async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        // Apply line limit if specified
        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * File write tool handler
 * TypeScript: async function with void return (string output for logging)
 * Python: def run_write(path: str, content: str) -> str
 */
async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);

        // Create parent directories if they don't exist
        // TypeScript: fs.mkdir with recursive option
        // Python: fp.parent.mkdir(parents=True, exist_ok=True)
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });

        await fs.writeFile(safeFilePath, content, "utf-8");

        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * File edit tool handler
 * TypeScript: async function
 * Python: def run_edit(path: str, old_text: str, new_text: str) -> str
 */
async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        // Check if old text exists
        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        // Replace only first occurrence (like Python's replace with count=1)
        const newContent = content.replace(oldText, newText);

        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Tool handler type
 * TypeScript: Function type with specific signature
 * Python: Callable with **kwargs
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: {tool_name: handler}
 *
 * TypeScript: Record<string, ToolHandler> - a typed object with string keys
 * Python: TOOL_HANDLERS = {"bash": lambda **kw: ..., "read": lambda **kw: ...}
 *
 * Key differences:
 * - TypeScript uses Record type for type-safe key-value pairs
 * - Each handler is an async function returning Promise<string>
 * - Arrow functions capture the handler functions with closures
 * - Type inference ensures handlers match the ToolHandler type
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    // TypeScript: Arrow function with destructuring and type assertion
    // Python: lambda **kw: run_bash(kw["command"])
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    // TypeScript: Optional chaining and type assertions
    // Python: lambda **kw: run_read(kw["path"], kw.get("limit"))
    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },
};

/**
 * Tool definitions for Anthropic API
 * TypeScript: Array of tool definition objects
 * Python: TOOLS = [{...}, {...}, ...]
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * THE CORE PATTERN: Agent loop (unchanged from s01!)
 *
 * The loop didn't change at all. We just added tools to the dispatch map.
 * This is the beauty of the pattern: extensibility without modification.
 *
 * TypeScript: async function with type-safe handler dispatch
 * Python: def agent_loop(messages: list) - same structure
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        // Append assistant turn
        messages.push({
            role: "assistant",
            content: response.content,
        });

        // If the model didn't call a tool, we're done
        if (response.stop_reason !== "tool_use") {
            return;
        }

        // Execute each tool call, collect results
        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            // TypeScript: Type guard for tool_use blocks
            // Python: if block.type == "tool_use"
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                // TypeScript: Get handler from map, execute with type safety
                // Python: handler = TOOL_HANDLERS.get(block.name); output = handler(**block.input)
                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    output = await handler(block.input);
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                // TypeScript: Type-safe tool result object
                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        // Append tool results as user message
        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 2: Tool Use. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms02 >> \x1b[0m");

            if (query.trim().toLowerCase() === "q" || query.trim().toLowerCase() === "exit" || query.trim() === "") {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: planning -- keeping the model on course without scripting the route.
// @ts-nocheck
/**
 * s03_todo_write.ts - TodoWrite
 *
 * The model tracks its own progress via a TodoManager. A nag reminder
 * forces it to keep updating when it forgets.
 *
 *     +----------+      +-------+      +---------+
 *     |   User   | ---> |  LLM  | ---> | Tools   |
 *     |  prompt  |      |       |      | + todo  |
 *     +----------+      +---+---+      +----+----+
 *                           ^               |
 *                           |   tool_result |
 *                           +---------------+
 *                                 |
 *                     +-----------+-----------+
 *                     | TodoManager state     |
 *                     | [ ] task A            |
 *                     | [>] task B <- doing   |
 *                     | [x] task C            |
 *                     +-----------------------+
 *                                 |
 *                     if rounds_since_todo >= 3:
 *                       inject <reminder>
 *
 * Key insight: "The agent can track its own progress -- and I can see it."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. CLASS DEFINITIONS:
 *    - Python: class TodoManager with __init__ method
 *    - TypeScript: class with constructor and property types
 *    - TypeScript requires explicit property declarations
 *
 * 2. ENUM USAGE:
 *    - Python: String literals for status ("pending", "in_progress", "completed")
 *    - TypeScript: enum for compile-time type safety
 *
 * 3. TYPE VALIDATION:
 *    - Python: Runtime type checking with isinstance()
 *    - TypeScript: Compile-time type checking + runtime validation
 *    - Both need runtime validation for API inputs
 *
 * 4. STATE MANAGEMENT:
 *    - Python: Instance variables (self.items = [])
 *    - TypeScript: Class properties with type annotations
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const SYSTEM = `You are a coding agent at ${WORKDIR}.
Use the todo tool to plan multi-step tasks. Mark in_progress before starting, completed when done.
Prefer tools over prose.`;

const execAsync = promisify(exec);

/**
 * Todo status enum
 * TypeScript: enum provides compile-time type safety
 * Python: String literals (no compile-time checking)
 */
enum TodoStatus {
    PENDING = "pending",
    IN_PROGRESS = "in_progress",
    COMPLETED = "completed",
}

/**
 * Todo item interface
 * TypeScript: Interface defines shape at compile time
 * Python: Would use TypedDict or runtime dict
 */
interface TodoItem {
    id: string;
    text: string;
    status: TodoStatus;
}

/**
 * Todo item input (from API)
 * TypeScript: Optional fields marked with ?
 * Python: Dict with all keys optional
 */
interface TodoItemInput {
    id?: string;
    text: string;
    status?: string;
}

/**
 * TodoManager: Structured state the LLM writes to
 *
 * TypeScript: Class with typed properties and methods
 * Python: class TodoManager: with __init__, update, render
 *
 * Key differences:
 * - TypeScript requires explicit property declarations (private items: TodoItem[])
 * - Constructor parameter types are mandatory
 * - Method return types are explicitly declared
 */
class TodoManager {
    // TypeScript: private property with type
    // Python: self.items = [] (in __init__)
    private items: TodoItem[] = [];

    /**
     * Update todo items with validation
     * TypeScript: Typed parameter and return type
     * Python: def update(self, items: list) -> str
     */
    update(itemsInput: TodoItemInput[]): string {
        // Validate max items
        if (itemsInput.length > 20) {
            throw new Error("Max 20 todos allowed");
        }

        const validated: TodoItem[] = [];
        let inProgressCount = 0;

        // Validate each item
        // TypeScript: for...of loop with explicit index
        // Python: for i, item in enumerate(items)
        for (let i = 0; i < itemsInput.length; i++) {
            const item = itemsInput[i];
            const text = String(item.text || "").trim();
            const statusStr = String(item.status || "pending").toLowerCase();
            const itemId = String(item.id || String(i + 1));

            // Validate text
            if (!text) {
                throw new Error(`Item ${itemId}: text required`);
            }

            // Validate status
            if (
                ![
                    TodoStatus.PENDING,
                    TodoStatus.IN_PROGRESS,
                    TodoStatus.COMPLETED,
                ].includes(statusStr as TodoStatus)
            ) {
                throw new Error(`Item ${itemId}: invalid status '${statusStr}'`);
            }

            const status = statusStr as TodoStatus;

            // Count in_progress items
            if (status === TodoStatus.IN_PROGRESS) {
                inProgressCount++;
            }

            validated.push({
                id: itemId,
                text,
                status,
            });
        }

        // Validate only one in_progress
        if (inProgressCount > 1) {
            throw new Error("Only one task can be in_progress at a time");
        }

        // Update internal state
        this.items = validated;

        // Return rendered output
        return this.render();
    }

    /**
     * Render todo items as formatted string
     * TypeScript: Returns string
     * Python: def render(self) -> str
     */
    render(): string {
        if (this.items.length === 0) {
            return "No todos.";
        }

        const lines: string[] = [];

        // Map status to marker
        // TypeScript: Record type for index signature
        // Python: Dict with literal keys
        const markers: Record<TodoStatus, string> = {
            [TodoStatus.PENDING]: "[ ]",
            [TodoStatus.IN_PROGRESS]: "[>]",
            [TodoStatus.COMPLETED]: "[x]",
        };

        // Render each item
        for (const item of this.items) {
            const marker = markers[item.status];
            lines.push(`${marker} #${item.id}: ${item.text}`);
        }

        // Add completion summary
        const completed = this.items.filter(
            (t) => t.status === TodoStatus.COMPLETED
        ).length;
        lines.push(`\n(${completed}/${this.items.length} completed)`);

        return lines.join("\n");
    }
}

// Create singleton instance
// TypeScript: const with class instantiation
// Python: TODO = TodoManager()
const TODO = new TodoManager();

/**
 * Tool implementations (same as s02)
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: Now includes todo handler!
 *
 * TypeScript: Record type with all tool handlers
 * Python: TOOL_HANDLERS = {..., "todo": lambda **kw: TODO.update(kw["items"])}
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },

    // TypeScript: Todo handler using class method
    // Python: lambda **kw: TODO.update(kw["items"])
    todo: async (input) => {
        const items = input.items as TodoItemInput[];
        return TODO.update(items);
    },
};

/**
 * Tool definitions - now includes todo!
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
    {
        name: "todo",
        description: "Update todo list. Use to plan and track progress on multi-step tasks.",
        input_schema: {
            type: "object" as const,
            properties: {
                items: {
                    type: "array",
                    items: {
                        type: "object",
                        properties: {
                            id: { type: "string" },
                            text: { type: "string" },
                            status: {
                                type: "string",
                                enum: [
                                    TodoStatus.PENDING,
                                    TodoStatus.IN_PROGRESS,
                                    TodoStatus.COMPLETED,
                                ],
                            },
                        },
                        required: ["text"],
                    },
                },
            },
            required: ["items"] as const,
        },
    },
];

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Agent loop with reminder system
 *
 * NEW: Tracks rounds since last todo update and injects reminders
 *
 * TypeScript: Parameter for rounds counter
 * Python: Uses closure variable or instance variable
 */
async function agentLoop(
    messages: Message[],
    roundsSinceTodo: { value: number }
): Promise<void> {
    // Inject reminder if needed
    // TypeScript: Check rounds counter
    // Python: if rounds_since_todo >= 3
    if (roundsSinceTodo.value >= 3) {
        const reminder: Message = {
            role: "user",
            content:
                "Reminder: You have an active todo list. Please update it with your progress.",
        };
        messages.push(reminder);
        roundsSinceTodo.value = 0;
    }

    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];
        let todoUsed = false;

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    output = await handler(block.input);
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                // Track if todo was used
                // TypeScript: String comparison
                // Python: if block.name == "todo"
                if (block.name === "todo") {
                    todoUsed = true;
                }

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });

        // Reset counter if todo was used
        // TypeScript: Conditional assignment
        // Python: rounds_since_todo = 0 if todo_used else rounds_since_todo + 1
        roundsSinceTodo.value = todoUsed ? 0 : roundsSinceTodo.value + 1;
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const history: Message[] = [];
    const roundsSinceTodo = { value: 0 };

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 3: Todo Write. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms03 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history, roundsSinceTodo);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: context isolation -- protecting the model's clarity of thought.
/**
 * s04_subagent.ts - Subagent
 *
 * Break big tasks down; each subtask gets a clean context.
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();
const execAsync = promisify(exec);

const SYSTEM = `You are a coding agent at ${WORKDIR}.
Use tools to complete the task. For broad exploration, use the task tool once and wait for its summary.`;

const SUBAGENT_SYSTEM = `You are a focused subagent at ${WORKDIR}.
Use tools as needed and return a concise summary of findings and outcomes.`;

function safePath(p: string): string {
    const resolvedPath = path.resolve(WORKDIR, p);
    if (!resolvedPath.startsWith(WORKDIR)) {
        throw new Error(`Path escapes workspace: ${p}`);
    }
    return resolvedPath;
}

async function runBash(command: string): Promise<string> {
    const blocked = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
    if (blocked.some((x) => command.includes(x))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });
        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error: any) {
        if (error?.code === "ETIMEDOUT") {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : String(error)}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");
        const lines = content.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = [...lines.slice(0, limit), `... (${lines.length - limit} more)`];
            return truncated.join("\n").slice(0, 50000);
        }

        return content.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : String(error)}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        await fs.mkdir(path.dirname(safeFilePath), { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : String(error)}`;
    }
}

async function runEdit(filePath: string, oldText: string, newText: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");
        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }
        await fs.writeFile(safeFilePath, content.replace(oldText, newText), "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : String(error)}`;
    }
}

type ToolHandler = (input: Record<string, any>) => Promise<string>;

const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => runBash(input.command),
    read_file: async (input) => runRead(input.path, input.limit),
    write_file: async (input) => runWrite(input.path, input.content),
    edit_file: async (input) => runEdit(input.path, input.old_text, input.new_text),
};

const CHILD_TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: { command: { type: "string" as const } },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: { path: { type: "string" as const }, limit: { type: "integer" as const } },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: { path: { type: "string" as const }, content: { type: "string" as const } },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" as const },
                old_text: { type: "string" as const },
                new_text: { type: "string" as const },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

const PARENT_TOOLS = [
    ...CHILD_TOOLS,
    {
        name: "task",
        description:
            "Spawn a subagent with fresh context. It shares the filesystem but not conversation history.",
        input_schema: {
            type: "object" as const,
            properties: {
                prompt: { type: "string" as const },
                description: { type: "string" as const, description: "Short description of the task" },
            },
            required: ["prompt"] as const,
        },
    },
];

async function runSubagent(prompt: string): Promise<string> {
    const subMessages: any[] = [{ role: "user", content: prompt }];
    let finalResponse: any = null;

    for (let i = 0; i < 30; i += 1) {
        finalResponse = await client.messages.create({
            model: MODEL,
            system: SUBAGENT_SYSTEM,
            messages: subMessages,
            tools: CHILD_TOOLS as any,
            max_tokens: 8000,
        });

        subMessages.push({ role: "assistant", content: finalResponse.content as any });
        if (finalResponse.stop_reason !== "tool_use") {
            break;
        }

        const results: any[] = [];
        for (const block of finalResponse.content as any[]) {
            if (block.type === "tool_use") {
                const handler = TOOL_HANDLERS[block.name as string];
                const output = handler
                    ? await handler((block.input || {}) as Record<string, any>)
                    : `Unknown tool: ${block.name}`;
                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: String(output).slice(0, 50000),
                });
            }
        }
        subMessages.push({ role: "user", content: results as any });
    }

    if (!finalResponse?.content) {
        return "(no summary)";
    }
    const text = (finalResponse.content as any[])
        .filter((b) => typeof b?.text === "string")
        .map((b) => b.text)
        .join("");
    return text || "(no summary)";
}

async function agentLoop(messages: any[]): Promise<void> {
    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages,
            tools: PARENT_TOOLS as any,
            max_tokens: 8000,
        });

        messages.push({ role: "assistant", content: response.content as any });
        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: any[] = [];
        for (const block of response.content as any[]) {
            if (block.type !== "tool_use") {
                continue;
            }

            let output: string;
            if (block.name === "task") {
                const desc = (block.input?.description as string) || "subtask";
                const prompt = (block.input?.prompt as string) || "";
                console.log(`> task (${desc}): ${prompt.slice(0, 80)}`);
                output = await runSubagent(prompt);
            } else {
                const handler = TOOL_HANDLERS[block.name as string];
                output = handler
                    ? await handler((block.input || {}) as Record<string, any>)
                    : `Unknown tool: ${block.name}`;
            }

            console.log(`  ${String(output).slice(0, 200)}`);
            results.push({
                type: "tool_result",
                tool_use_id: block.id,
                content: String(output),
            });
        }

        messages.push({ role: "user", content: results as any });
    }
}

async function main(): Promise<void> {
    const history: any[] = [];
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });
    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 4: Subagent. Type 'q' to exit.\n");
    try {
        while (true) {
            const query = await question("\x1b[36ms04 >> \x1b[0m");
            if (query.trim().toLowerCase() === "q" || query.trim() === "") {
                break;
            }
            history.push({ role: "user", content: query });
            await agentLoop(history);
        }
    } finally {
        rl.close();
    }
}

main().catch((error) => {
    console.error(error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: on-demand knowledge -- domain expertise, loaded when the model asks.
// @ts-nocheck
/**
 * s05_skill_loading.ts - Skills
 *
 * Two-layer skill injection that avoids bloating the system prompt:
 *
 *     Layer 1 (cheap): skill names in system prompt (~100 tokens/skill)
 *     Layer 2 (on demand): full skill body in tool_result
 *
 *     skills/
 *       pdf/
 *         SKILL.md          <-- frontmatter (name, description) + body
 *       code-review/
 *         SKILL.md
 *
 *     System prompt:
 *     +--------------------------------------+
 *     | You are a coding agent.              |
 *     | Skills available:                    |
 *     |   - pdf: Process PDF files...        |  <-- Layer 1: metadata only
 *     |   - code-review: Review code...      |
 *     +--------------------------------------+
 *
 *     When model calls load_skill("pdf"):
 *     +--------------------------------------+
 *     | tool_result:                         |
 *     | <skill>                              |
 *     |   Full PDF processing instructions   |  <-- Layer 2: full body
 *     |   Step 1: ...                        |
 *     |   Step 2: ...                        |
 *     | </skill>                             |
 *     +--------------------------------------+
 *
 * Key insight: "Don't put everything in the system prompt. Load on demand."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. YAML PARSING:
 *    - Python: Uses regex or PyYAML for frontmatter
 *    - TypeScript: Can use regex (like Python) or js-yaml library
 *    - This implementation uses regex for simplicity (no extra dependency)
 *
 * 2. FILE SYSTEM SCANNING:
 *    - Python: pathlib.Path.rglob("SKILL.md") for recursive search
 *    - TypeScript: fs.promises.readdir with recursive option or manual traversal
 *    - This implementation uses a simple recursive approach
 *
 * 3. TYPED FRONTMATTER:
 *    - Python: Dict with runtime keys
 *    - TypeScript: Interface with compile-time checking
 *    - Optional fields marked with ? operator
 *
 * 4. ERROR HANDLING:
 *    - Python: try/except with Exception
 *    - TypeScript: try/catch with proper error typing
 *    - Both return user-friendly error messages
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const SKILLS_DIR = path.join(WORKDIR, "skills");
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

/**
 * Skill metadata interface
 * TypeScript: Interface with optional fields
 * Python: Dict with runtime keys
 */
interface SkillMetadata {
    name?: string;
    description?: string;
    tags?: string;
    [key: string]: string | undefined;
}

/**
 * Skill data structure
 * TypeScript: Interface with explicit types
 * Python: Dict with nested structure
 */
interface Skill {
    meta: SkillMetadata;
    body: string;
    path: string;
}

/**
 * SkillLoader: Scan skills/<name>/SKILL.md with YAML frontmatter
 *
 * TypeScript: Class with typed properties and methods
 * Python: class SkillLoader with __init__ and methods
 *
 * Key differences:
 * - TypeScript uses async/await for file operations
 * - Constructor is async in pattern (using init method)
 * - Explicit property types for metadata and skills
 */
class SkillLoader {
    private skillsDir: string;
    private skills: Map<string, Skill> = new Map();

    constructor(skillsDir: string) {
        this.skillsDir = skillsDir;
    }

    /**
     * Initialize by loading all skills
     * TypeScript: async method (can't be async in constructor)
     * Python: __init__ calls self._load_all() (synchronous)
     */
    async init(): Promise<void> {
        await this.loadAll();
    }

    /**
     * Recursively find and load all SKILL.md files
     * TypeScript: async/await with fs.readdir
     * Python: pathlib.Path.rglob("SKILL.md") (synchronous)
     */
    private async loadAll(): Promise<void> {
        try {
            await this.scanDirectory(this.skillsDir);
        } catch (error) {
            // Directory doesn't exist or isn't readable
            if (error instanceof Error && "code" in error && error.code !== "ENOENT") {
                console.error("Error loading skills:", error);
            }
        }
    }

    /**
     * Recursively scan directory for SKILL.md files
     * TypeScript: Manual recursive implementation
     * Python: rglob does this automatically
     */
    private async scanDirectory(dir: string): Promise<void> {
        try {
            const entries = await fs.readdir(dir, { withFileTypes: true });

            for (const entry of entries) {
                const fullPath = path.join(dir, entry.name);

                if (entry.isDirectory()) {
                    await this.scanDirectory(fullPath);
                } else if (entry.name === "SKILL.md") {
                    await this.loadSkillFile(fullPath);
                }
            }
        } catch (error) {
            // Skip directories we can't read
        }
    }

    /**
     * Load a single skill file
     */
    private async loadSkillFile(filePath: string): Promise<void> {
        try {
            const text = await fs.readFile(filePath, "utf-8");
            const { meta, body } = this.parseFrontmatter(text);
            const name = meta.name || path.basename(path.dirname(filePath));
            this.skills.set(name, {
                meta,
                body,
                path: filePath,
            });
        } catch (error) {
            console.error(`Error loading skill ${filePath}:`, error);
        }
    }

    /**
     * Parse YAML frontmatter between --- delimiters
     * TypeScript: RegExp with DOTALL flag (s in regex)
     * Python: re.match(r"^---\n(.*?)\n---\n(.*)", text, re.DOTALL)
     *
     * Note: This is a simple YAML parser. For production,
     * use the 'yaml' or 'js-yaml' package for full YAML support.
     */
    private parseFrontmatter(text: string): { meta: SkillMetadata; body: string } {
        // TypeScript: RegExp with /s flag for DOTALL
        // Python: re.DOTALL flag
        const match = text.match(/^---\n(.*?)\n---\n(.*)/s);

        if (!match) {
            return { meta: {}, body: text };
        }

        const meta: SkillMetadata = {};
        const frontmatterLines = match[1].trim().split("\n");

        // TypeScript: for...of loop for iteration
        // Python: for line in match.group(1).strip().splitlines()
        for (const line of frontmatterLines) {
            // TypeScript: String includes() method
            // Python: if ":" in line
            if (line.includes(":")) {
                // TypeScript: String split with limit
                // Python: key, val = line.split(":", 1)
                const colonIndex = line.indexOf(":");
                const key = line.slice(0, colonIndex).trim();
                const val = line.slice(colonIndex + 1).trim();
                meta[key] = val;
            }
        }

        return {
            meta,
            body: match[2].trim(),
        };
    }

    /**
     * Layer 1: Short descriptions for the system prompt
     * TypeScript: Returns string
     * Python: def get_descriptions(self) -> str
     */
    getDescriptions(): string {
        if (this.skills.size === 0) {
            return "(no skills available)";
        }

        const lines: string[] = [];

        // TypeScript: for...of with Map.entries()
        // Python: for name, skill in self.skills.items()
        for (const [name, skill] of this.skills.entries()) {
            const desc = skill.meta.description || "No description";
            const tags = skill.meta.tags || "";
            let line = `  - ${name}: ${desc}`;
            if (tags) {
                line += ` [${tags}]`;
            }
            lines.push(line);
        }

        return lines.join("\n");
    }

    /**
     * Layer 2: Full skill body returned in tool_result
     * TypeScript: Returns formatted string with XML tags
     * Python: f"<skill name=\"{name}\">\n{skill['body']}\n</skill>"
     */
    getContent(name: string): string {
        const skill = this.skills.get(name);

        if (!skill) {
            const available = Array.from(this.skills.keys()).join(", ");
            return `Error: Unknown skill '${name}'. Available: ${available}`;
        }

        return `<skill name="${name}">\n${skill.body}\n</skill>`;
    }

    /**
     * Get list of available skill names
     */
    getSkillNames(): string[] {
        return Array.from(this.skills.keys());
    }
}

/**
 * Initialize skill loader
 * TypeScript: await async initialization
 * Python: SKILL_LOADER = SkillLoader(SKILLS_DIR) (synchronous)
 */
const SKILL_LOADER = new SkillLoader(SKILLS_DIR);
SKILL_LOADER.init().catch((error) => {
    console.error("Failed to initialize skill loader:", error);
});

/**
 * Layer 1: Skill metadata injected into system prompt
 * TypeScript: Template literal with async loader
 * Python: f-string with method call
 */
const SYSTEM = `You are a coding agent at ${WORKDIR}.
Use load_skill to access specialized knowledge before tackling unfamiliar topics.

Skills available:
${SKILL_LOADER.getDescriptions()}`;

/**
 * Tool implementations (same as s04)
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

const execAsync = promisify(exec);

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: Now includes load_skill handler!
 *
 * TypeScript: Record with load_skill handler
 * Python: TOOL_HANDLERS = {..., "load_skill": lambda **kw: SKILL_LOADER.get_content(kw["name"])}
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },

    // TypeScript: Skill loader handler
    // Python: lambda **kw: SKILL_LOADER.get_content(kw["name"])
    load_skill: async (input) => {
        const name = input.name as string;
        return SKILL_LOADER.getContent(name);
    },
};

/**
 * Tool definitions - now includes load_skill!
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
    {
        name: "load_skill",
        description: "Load specialized knowledge by name.",
        input_schema: {
            type: "object" as const,
            properties: {
                name: {
                    type: "string",
                    description: "Skill name to load",
                },
            },
            required: ["name"] as const,
        },
    },
];

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Agent loop (same as s04)
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    try {
                        output = await handler(block.input);
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 5: Skill Loading. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms05 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: context durability -- enabling infinite sessions through compression.
// @ts-nocheck
/**
 * s06_context_compact.ts - Compact
 *
 * Three-layer compression pipeline so the agent can work forever:
 *
 *     Every turn:
 *     +------------------+
 *     | Tool call result |
 *     +------------------+
 *             |
 *             v
 *     [Layer 1: micro_compact]        (silent, every turn)
 *       Replace tool_result content older than last 3
 *       with "[Previous: used {tool_name}]"
 *             |
 *             v
 *     [Check: tokens > 50000?]
 *        |               |
 *        no              yes
 *        |               |
 *        v               v
 *     continue    [Layer 2: auto_compact]
 *                   Save full transcript to .transcripts/
 *                   Ask LLM to summarize conversation.
 *                   Replace all messages with [summary].
 *                         |
 *                         v
 *                 [Layer 3: compact tool]
 *                   Model calls compact -> immediate summarization.
 *                   Same as auto, triggered manually.
 *
 * Key insight: "The agent can forget strategically and keep working forever."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. JSON SERIALIZATION:
 *    - Python: json.dumps(msg, default=str) for complex objects
 *    - TypeScript: JSON.stringify() with replacer function
 *    - Both need to handle non-serializable objects
 *
 * 2. FILE I/O:
 *    - Python: with open(path, "w") as f: f.write(...)
 *    - TypeScript: await fs.writeFile(path, data) (async)
 *    - TypeScript requires async/await for file operations
 *
 * 3. ARRAY MUTATION:
 *    - Python: Direct mutation of lists and dicts
 *    - TypeScript: Can mutate, but type safety ensures structure
 *    - Both modify messages in place for micro_compact
 *
 * 4. TOKEN ESTIMATION:
 *    - Python: len(str(messages)) // 4
 *    - TypeScript: JSON.stringify(messages).length / 4
 *    - Both use rough estimation (same algorithm)
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`;

// Configuration
const THRESHOLD = 50000;
const TRANSCRIPT_DIR = path.join(WORKDIR, ".transcripts");
const KEEP_RECENT = 3;
const PRESERVE_RESULT_TOOLS = new Set(["read_file"]);

/**
 * Rough token count: ~4 chars per token
 * TypeScript: Returns number
 * Python: def estimate_tokens(messages: list) -> int
 */
function estimateTokens(messages: Message[]): number {
    // TypeScript: JSON.stringify with replacer for complex objects
    // Python: len(str(messages))
    const jsonString = JSON.stringify(messages, (_, value) => {
        if (typeof value === "object" && value !== null) {
            if ("type" in value && "text" in value) {
                return { type: value.type, text: value.text };
            }
        }
        return value;
    });
    return Math.floor(jsonString.length / 4);
}

/**
 * LAYER 1: micro_compact - Replace old tool results with placeholders
 *
 * This runs silently every turn to keep context size manageable.
 * Keeps the last N tool results with full content, replaces older ones
 * with brief placeholders.
 *
 * TypeScript: Returns modified Message array (mutates in place)
 * Python: def micro_compact(messages: list) -> list
 */
function microCompact(messages: Message[]): Message[] {
    // Collect all tool_result entries with their indices
    // TypeScript: Array of tuples
    // Python: tool_results = []
    interface ToolResultEntry {
        msgIdx: number;
        partIdx: number;
        result: ToolResultBlock;
    }

    const toolResults: ToolResultEntry[] = [];

    for (let msgIdx = 0; msgIdx < messages.length; msgIdx++) {
        const msg = messages[msgIdx];
        if (msg.role === "user" && Array.isArray(msg.content)) {
            for (let partIdx = 0; partIdx < msg.content.length; partIdx++) {
                const part = msg.content[partIdx];
                if (part.type === "tool_result") {
                    toolResults.push({
                        msgIdx,
                        partIdx,
                        result: part as ToolResultBlock,
                    });
                }
            }
        }
    }

    // If we have fewer results than KEEP_RECENT, nothing to do
    if (toolResults.length <= KEEP_RECENT) {
        return messages;
    }

    // Find tool_name for each result by matching tool_use_id in assistant messages
    // TypeScript: Map for O(1) lookups
    // Python: tool_name_map = {}
    const toolNameMap = new Map<string, string>();

    for (const msg of messages) {
        if (msg.role === "assistant" && Array.isArray(msg.content)) {
            for (const block of msg.content) {
                if (block.type === "tool_use" && "id" in block && "name" in block) {
                    toolNameMap.set(block.id as string, block.name as string);
                }
            }
        }
    }

    // Clear old results (keep last KEEP_RECENT)
    // TypeScript: Slice array to get old results
    // Python: to_clear = tool_results[:-KEEP_RECENT]
    const toClear = toolResults.slice(0, -KEEP_RECENT);

    for (const { result } of toClear) {
        if (
            typeof result.content !== "string" ||
            result.content.length <= 100
        ) {
            continue;
        }
        const toolId = result.tool_use_id;
        const toolName = toolNameMap.get(toolId) || "unknown";
        // Preserve read_file outputs — they are reference material;
        // compacting them forces the agent to re-read files.
        if (PRESERVE_RESULT_TOOLS.has(toolName)) continue;
        result.content = `[Previous: used ${toolName}]`;
    }

    return messages;
}

/**
 * LAYER 2: auto_compact - Save transcript, summarize, replace messages
 *
 * When context exceeds threshold, save full transcript and ask LLM
 * to summarize. Then replace all messages with the summary.
 *
 * TypeScript: async function returning new Message array
 * Python: def auto_compact(messages: list) -> list
 */
async function autoCompact(messages: Message[]): Promise<Message[]> {
    // Create transcript directory if it doesn't exist
    // TypeScript: await fs.mkdir
    // Python: TRANSCRIPT_DIR.mkdir(exist_ok=True)
    await fs.mkdir(TRANSCRIPT_DIR, { recursive: true });

    // Save full transcript to disk
    // TypeScript: Timestamp with Date.now()
    // Python: int(time.time())
    const timestamp = Date.now();
    const transcriptPath = path.join(TRANSCRIPT_DIR, `transcript_${timestamp}.jsonl`);

    // Write each message as a JSON line
    // TypeScript: JSON.stringify with replacer
    // Python: json.dumps(msg, default=str)
    const lines = messages.map((msg) =>
        JSON.stringify(msg, (_, value) => {
            // Handle complex objects
            if (typeof value === "object" && value !== null) {
                if ("type" in value) {
                    return value;
                }
            }
            return value;
        })
    );

    await fs.writeFile(transcriptPath, lines.join("\n") + "\n", "utf-8");
    console.log(`[transcript saved: ${transcriptPath}]`);

    // Ask LLM to summarize
    // TypeScript: Limit string with slice
    // Python: conversation_text = json.dumps(messages, default=str)[:80000]
    const conversationText = JSON.stringify(
        messages,
        (_, value) => {
            if (typeof value === "object" && value !== null) {
                if ("type" in value) {
                    return value;
                }
            }
            return value;
        }
    ).slice(-80000);

    const summaryResponse = await client.messages.create({
        model: MODEL,
        messages: [
            {
                role: "user",
                content:
                    "Summarize this conversation for continuity. Include: " +
                    "1) What was accomplished, 2) Current state, 3) Key decisions made. " +
                    "Be concise but preserve critical details.\n\n" +
                    conversationText,
            },
        ],
        max_tokens: 2000,
    });

    // Collect text from ALL text blocks (not just the first -- model may put text after tool_use blocks)
    const summary =
        summaryResponse.content
            .filter((block: any) => block.type === "text")
            .map((block: any) => block.text)
            .join("\n")
            .trim() || "Summary unavailable";

    // Replace all messages with compressed summary
    // TypeScript: Return new array
    // Python: return [{...}, {...}]
    return [
        {
            role: "user",
            content: `[Conversation compressed. Transcript: ${transcriptPath}]\n\n${summary}`,
        },
    ];
}

/**
 * Tool implementations (same as s05)
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

const execAsync = promisify(exec);

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Message types
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: Now includes compact handler!
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },

    // LAYER 3: compact tool - manual compression trigger
    // TypeScript: Returns message (same as Python)
    // Python: lambda **kw: "Manual compression requested."
    compact: async () => {
        return "Manual compression requested.";
    },
};

/**
 * Tool definitions - now includes compact!
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
    {
        name: "compact",
        description: "Manually compress conversation context by summarizing and archiving.",
        input_schema: {
            type: "object" as const,
            properties: {},
            required: [] as const,
        },
    },
];

/**
 * Agent loop with context compression
 *
 * NEW: Three-layer compression pipeline
 * 1. micro_compact after every tool result
 * 2. auto_compact when tokens exceed threshold
 * 3. compact tool for manual triggering
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        // LAYER 1: micro_compact every turn (silent)
        // TypeScript: Function call mutates messages
        // Python: messages = micro_compact(messages)
        microCompact(messages);

        // LAYER 2: auto_compact if over threshold
        // TypeScript: await async function
        // Python: if estimate_tokens(messages) > THRESHOLD: messages = await auto_compact(messages)
        if (estimateTokens(messages) > THRESHOLD) {
            console.log("[auto-compacting context...]");
            messages = await autoCompact(messages);
        }

        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];
        let compactRequested = false;

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    try {
                        output = await handler(block.input);
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                // LAYER 3: Check if compact was manually requested
                // TypeScript: String comparison
                // Python: if block.name == "compact"
                if (block.name === "compact") {
                    compactRequested = true;
                }

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });

        // If compact was manually requested, trigger auto_compact
        if (compactRequested) {
            console.log("[manual compact triggered...]");
            messages = await autoCompact(messages);
            return;
        }
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 6: Context Compact. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms06 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: safety -- the pipeline between intent and execution.
// @ts-nocheck
/**
 * s07_permission_system.ts - Permission System
 *
 * Every tool call passes through a permission pipeline before execution.
 *
 * Teaching pipeline:
 *   1. deny rules
 *   2. mode check
 *   3. allow rules
 *   4. ask user
 *
 * This version intentionally teaches three modes first:
 *   - default
 *   - plan
 *   - auto
 *
 * That is enough to build a real, understandable permission system without
 * burying readers under every advanced policy branch on day one.
 *
 * Key insight: "Safety is a pipeline, not a boolean."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. REGEX VALIDATION:
 *    - Python: re.search(pattern, command) directly
 *    - TypeScript: new RegExp(pattern).test(command)
 *    - Both return boolean match results
 *
 * 2. RULE MATCHING (fnmatch):
 *    - Python: fnmatch(path, pattern) for glob matching
 *    - TypeScript: simple globMatch() helper using * wildcards
 *    - Both support * wildcard patterns for path/content matching
 *
 * 3. INPUT/OUTPUT:
 *    - Python: input() for interactive prompts
 *    - TypeScript: readline.question() promisified
 *    - Both block for user input in the same way
 *
 * 4. PERMISSION CHECK PIPELINE:
 *    - Python: dict return {"behavior": str, "reason": str}
 *    - TypeScript: object return {behavior: string, reason: string}
 *    - Same structure, same semantics
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const execAsync = promisify(exec);

// -- Permission modes --
// Teaching version starts with three clear modes first.
const MODES = ["default", "plan", "auto"] as const;
type PermissionMode = (typeof MODES)[number];

const READ_ONLY_TOOLS = new Set(["read_file", "bash_readonly"]);

// Tools that modify state
const WRITE_TOOLS = new Set(["write_file", "edit_file", "bash"]);

// -- Glob matching helper (replaces Python fnmatch) --
/**
 * Simple glob match supporting * wildcard.
 * TypeScript: Standalone function
 * Python: from fnmatch import fnmatch
 */
function globMatch(str: string, pattern: string): boolean {
    if (pattern === "*") return true;
    // Convert glob pattern to regex: * -> .*, ? -> ., escape rest
    const regexStr = pattern
        .replace(/[.+^${}()|[\]\\]/g, "\\$&")
        .replace(/\*/g, ".*")
        .replace(/\?/g, ".");
    return new RegExp(`^${regexStr}$`).test(str);
}

// -- Bash security validation --
/**
 * Validate bash commands for obviously dangerous patterns.
 *
 * The teaching version deliberately keeps this small and easy to read.
 * First catch a few high-risk patterns, then let the permission pipeline
 * decide whether to deny or ask the user.
 *
 * TypeScript: Class with static VALIDATORS array
 * Python: class BashSecurityValidator with class-level VALIDATORS
 */
class BashSecurityValidator {
    static VALIDATORS: [string, string][] = [
        ["shell_metachar", "[;&|`$]"],       // shell metacharacters
        ["sudo", "\\bsudo\\b"],              // privilege escalation
        ["rm_rf", "\\brm\\s+(-[a-zA-Z]*)?r"], // recursive delete
        ["cmd_substitution", "\\$\\("],      // command substitution
        ["ifs_injection", "\\bIFS\\s*="],    // IFS manipulation
    ];

    /**
     * Check a bash command against all validators.
     *
     * Returns list of [validator_name, matched_pattern] tuples for failures.
     * An empty list means the command passed all validators.
     *
     * TypeScript: [string, string][] return type
     * Python: List[Tuple[str, str]] return type
     */
    validate(command: string): [string, string][] {
        const failures: [string, string][] = [];
        for (const [name, pattern] of BashSecurityValidator.VALIDATORS) {
            if (new RegExp(pattern).test(command)) {
                failures.push([name, pattern]);
            }
        }
        return failures;
    }

    /**
     * Convenience: returns true only if no validators triggered.
     */
    isSafe(command: string): boolean {
        return this.validate(command).length === 0;
    }

    /**
     * Human-readable summary of validation failures.
     */
    describeFailures(command: string): string {
        const failures = this.validate(command);
        if (!failures.length) {
            return "No issues detected";
        }
        const parts = failures.map(([name, pattern]) => `${name} (pattern: ${pattern})`);
        return "Security flags: " + parts.join(", ");
    }
}

// -- Workspace trust --
/**
 * Check if a workspace has been explicitly marked as trusted.
 *
 * The teaching version uses a simple marker file. A more complete system
 * can layer richer trust flows on top of the same idea.
 *
 * TypeScript: async function using fs.access
 * Python: synchronous Path.exists()
 */
async function isWorkspaceTrusted(workspace?: string): Promise<boolean> {
    const ws = workspace || WORKDIR;
    const trustMarker = path.join(ws, ".claude", ".claude_trusted");
    try {
        await fs.access(trustMarker);
        return true;
    } catch {
        return false;
    }
}

// Singleton validator instance used by the permission pipeline
const bashValidator = new BashSecurityValidator();

// -- Permission rules --
// Rules are checked in order: first match wins.
// Format: { tool: string, path?: string, content?: string, behavior: "allow"|"deny"|"ask" }
const DEFAULT_RULES: PermissionRule[] = [
    // Always deny dangerous patterns
    { tool: "bash", content: "rm -rf /", behavior: "deny" },
    { tool: "bash", content: "sudo *", behavior: "deny" },
    // Allow reading anything
    { tool: "read_file", path: "*", behavior: "allow" },
];

interface PermissionRule {
    tool: string;
    path?: string;
    content?: string;
    behavior: "allow" | "deny" | "ask";
}

interface PermissionDecision {
    behavior: "allow" | "deny" | "ask";
    reason: string;
}

/**
 * Manages permission decisions for tool calls.
 *
 * Pipeline: deny_rules -> mode_check -> allow_rules -> ask_user
 *
 * The teaching version keeps the decision path short on purpose so readers
 * can implement it themselves before adding more advanced policy layers.
 *
 * TypeScript: Class with typed properties
 * Python: class PermissionManager with __init__
 */
class PermissionManager {
    mode: PermissionMode;
    rules: PermissionRule[];
    consecutiveDenials: number;
    maxConsecutiveDenials: number;

    constructor(mode: PermissionMode = "default", rules?: PermissionRule[]) {
        if (!MODES.includes(mode)) {
            throw new Error(`Unknown mode: ${mode}. Choose from ${MODES.join(", ")}`);
        }
        this.mode = mode;
        this.rules = rules ?? [...DEFAULT_RULES];
        // Simple denial tracking helps surface when the agent is repeatedly
        // asking for actions the system will not allow.
        this.consecutiveDenials = 0;
        this.maxConsecutiveDenials = 3;
    }

    /**
     * Check tool call against the permission pipeline.
     *
     * Returns: { behavior: "allow"|"deny"|"ask", reason: string }
     *
     * TypeScript: Returns typed PermissionDecision
     * Python: Returns dict with same keys
     */
    check(toolName: string, toolInput: Record<string, any>): PermissionDecision {
        // Step 0: Bash security validation (before deny rules)
        // Teaching version checks early for clarity.
        if (toolName === "bash") {
            const command = (toolInput.command as string) || "";
            const failures = bashValidator.validate(command);
            if (failures.length > 0) {
                // Severe patterns (sudo, rm_rf) get immediate deny
                const severe = new Set(["sudo", "rm_rf"]);
                const severeHits = failures.filter(([name]) => severe.has(name));
                if (severeHits.length > 0) {
                    const desc = bashValidator.describeFailures(command);
                    return {
                        behavior: "deny",
                        reason: `Bash validator: ${desc}`,
                    };
                }
                // Other patterns escalate to ask (user can still approve)
                const desc = bashValidator.describeFailures(command);
                return {
                    behavior: "ask",
                    reason: `Bash validator flagged: ${desc}`,
                };
            }
        }

        // Step 1: Deny rules (bypass-immune, checked first always)
        for (const rule of this.rules) {
            if (rule.behavior !== "deny") continue;
            if (this._matches(rule, toolName, toolInput)) {
                return {
                    behavior: "deny",
                    reason: `Blocked by deny rule: ${JSON.stringify(rule)}`,
                };
            }
        }

        // Step 2: Mode-based decisions
        if (this.mode === "plan") {
            // Plan mode: deny all write operations, allow reads
            if (WRITE_TOOLS.has(toolName)) {
                return {
                    behavior: "deny",
                    reason: "Plan mode: write operations are blocked",
                };
            }
            return { behavior: "allow", reason: "Plan mode: read-only allowed" };
        }

        if (this.mode === "auto") {
            // Auto mode: auto-allow read-only tools, ask for writes
            if (READ_ONLY_TOOLS.has(toolName) || toolName === "read_file") {
                return {
                    behavior: "allow",
                    reason: "Auto mode: read-only tool auto-approved",
                };
            }
            // Teaching: fall through to allow rules, then ask
        }

        // Step 3: Allow rules
        for (const rule of this.rules) {
            if (rule.behavior !== "allow") continue;
            if (this._matches(rule, toolName, toolInput)) {
                this.consecutiveDenials = 0;
                return {
                    behavior: "allow",
                    reason: `Matched allow rule: ${JSON.stringify(rule)}`,
                };
            }
        }

        // Step 4: Ask user (default behavior for unmatched tools)
        return {
            behavior: "ask",
            reason: `No rule matched for ${toolName}, asking user`,
        };
    }

    /**
     * Interactive approval prompt. Returns true if approved.
     *
     * TypeScript: Uses passed-in readline question function
     * Python: Uses input() directly
     */
    async askUser(
        toolName: string,
        toolInput: Record<string, any>,
        askFn: (prompt: string) => Promise<string>
    ): Promise<boolean> {
        const preview = JSON.stringify(toolInput).slice(0, 200);
        console.log(`\n  [Permission] ${toolName}: ${preview}`);
        const answer = (await askFn("  Allow? (y/n/always): ")).trim().toLowerCase();

        if (answer === "always") {
            // Add permanent allow rule for this tool
            this.rules.push({ tool: toolName, path: "*", behavior: "allow" });
            this.consecutiveDenials = 0;
            return true;
        }
        if (answer === "y" || answer === "yes") {
            this.consecutiveDenials = 0;
            return true;
        }

        // Track denials for circuit breaker
        this.consecutiveDenials += 1;
        if (this.consecutiveDenials >= this.maxConsecutiveDenials) {
            console.log(
                `  [${this.consecutiveDenials} consecutive denials -- ` +
                `consider switching to plan mode]`
            );
        }
        return false;
    }

    /**
     * Check if a rule matches the tool call.
     *
     * TypeScript: Method with typed parameters
     * Python: _matches(rule, tool_name, tool_input)
     */
    _matches(rule: PermissionRule, toolName: string, toolInput: Record<string, any>): boolean {
        // Tool name match
        if (rule.tool && rule.tool !== "*") {
            if (rule.tool !== toolName) return false;
        }
        // Path pattern match
        if ("path" in rule && rule.path && rule.path !== "*") {
            const filePath = (toolInput.path as string) || "";
            if (!globMatch(filePath, rule.path)) return false;
        }
        // Content pattern match (for bash commands)
        if ("content" in rule && rule.content) {
            const command = (toolInput.command as string) || "";
            if (!globMatch(command, rule.content)) return false;
        }
        return true;
    }
}

// -- Tool implementations --
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

async function runBash(command: string): Promise<string> {
    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });
        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error: any) {
        if (error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },
};

/**
 * Tool definitions
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

/**
 * Message types
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.
The user controls permissions. Some tool calls may be denied.`;

/**
 * The permission-aware agent loop.
 *
 * For each tool call:
 *   1. LLM requests tool use
 *   2. Permission pipeline checks: deny_rules -> mode -> allow_rules -> ask
 *   3. If allowed: execute tool, return result
 *   4. If denied: return rejection message to LLM
 *
 * TypeScript: async function with PermissionManager parameter
 * Python: def agent_loop(messages, perms)
 */
async function agentLoop(
    messages: Message[],
    perms: PermissionManager,
    askFn: (prompt: string) => Promise<string>
): Promise<void> {
    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type !== "tool_use" || !block.id || !block.name) continue;

            const toolInput = (block.input as Record<string, any>) || {};

            // -- Permission check --
            const decision = perms.check(block.name, toolInput);

            let output: string;

            if (decision.behavior === "deny") {
                output = `Permission denied: ${decision.reason}`;
                console.log(`  [DENIED] ${block.name}: ${decision.reason}`);
            } else if (decision.behavior === "ask") {
                const approved = await perms.askUser(block.name, toolInput, askFn);
                if (approved) {
                    const handler = TOOL_HANDLERS[block.name];
                    try {
                        output = handler
                            ? await handler(toolInput)
                            : `Unknown: ${block.name}`;
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                    console.log(`> ${block.name}: ${output.slice(0, 200)}`);
                } else {
                    output = `Permission denied by user for ${block.name}`;
                    console.log(`  [USER DENIED] ${block.name}`);
                }
            } else {
                // allow
                const handler = TOOL_HANDLERS[block.name];
                try {
                    output = handler
                        ? await handler(toolInput)
                        : `Unknown: ${block.name}`;
                } catch (error) {
                    output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                }
                console.log(`> ${block.name}: ${output.slice(0, 200)}`);
            }

            results.push({
                type: "tool_result",
                tool_use_id: block.id,
                content: output,
            });
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    // Choose permission mode at startup
    console.log("Permission modes: default, plan, auto");
    const modeInput = (await question("Mode (default): ")).trim().toLowerCase() || "default";
    const mode = (MODES as readonly string[]).includes(modeInput)
        ? (modeInput as PermissionMode)
        : "default";

    const perms = new PermissionManager(mode);
    console.log(`[Permission mode: ${mode}]`);

    const history: Message[] = [];

    console.log("Session 7: Permission System. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms07 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            // /mode command to switch modes at runtime
            if (query.startsWith("/mode")) {
                const parts = query.trim().split(/\s+/);
                if (parts.length === 2 && (MODES as readonly string[]).includes(parts[1])) {
                    perms.mode = parts[1] as PermissionMode;
                    console.log(`[Switched to ${parts[1]} mode]`);
                } else {
                    console.log(`Usage: /mode <${MODES.join("|")}>`);
                }
                continue;
            }

            // /rules command to show current rules
            if (query.trim() === "/rules") {
                perms.rules.forEach((rule, i) => {
                    console.log(`  ${i}: ${JSON.stringify(rule)}`);
                });
                continue;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history, perms, question);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: extensibility -- injecting behavior without touching the loop.
// @ts-nocheck
/**
 * s08_hook_system.ts - Hook System
 *
 * Hooks are extension points around the main loop.
 * They let readers add behavior without rewriting the loop itself.
 *
 * Teaching version:
 *   - SessionStart
 *   - PreToolUse
 *   - PostToolUse
 *
 * Teaching exit-code contract:
 *   - 0 -> continue
 *   - 1 -> block
 *   - 2 -> inject a message
 *
 * This is intentionally simpler than a production system. The goal here is to
 * teach the extension pattern clearly before introducing event-specific edge
 * cases.
 *
 * Key insight: "Extend the agent without touching the loop."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. SUBPROCESS EXECUTION:
 *    - Python: subprocess.run(command, shell=True, capture_output=True, ...)
 *    - TypeScript: execAsync(command, { cwd, env, timeout }) with promisified exec
 *    - Both capture stdout/stderr, both support timeouts
 *
 * 2. HOOK CONFIG LOADING:
 *    - Python: json.loads(config_path.read_text())
 *    - TypeScript: JSON.parse(await fs.readFile(configPath, "utf-8"))
 *    - TypeScript requires async for file reads
 *
 * 3. EXIT CODE HANDLING:
 *    - Python: r.returncode for subprocess exit codes
 *    - TypeScript: Check error.code field when execAsync throws
 *    - Both follow the same 0/1/2 contract
 *
 * 4. ENVIRONMENT VARIABLES:
 *    - Python: dict(os.environ) to copy env
 *    - TypeScript: { ...process.env } to spread-copy env
 *    - Both pass modified env to child process
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const execAsync = promisify(exec);

// The teaching version keeps only the three clearest events. More complete
// systems can grow the event surface later.
const HOOK_EVENTS = ["PreToolUse", "PostToolUse", "SessionStart"] as const;
type HookEvent = (typeof HOOK_EVENTS)[number];
const HOOK_TIMEOUT = 30; // seconds
// Real CC timeouts:
//   TOOL_HOOK_EXECUTION_TIMEOUT_MS = 600000 (10 minutes for tool hooks)
//   SESSION_END_HOOK_TIMEOUT_MS = 1500 (1.5 seconds for SessionEnd hooks)

// Workspace trust marker. Hooks only run if this file exists (or SDK mode).
const TRUST_MARKER = path.join(WORKDIR, ".claude", ".claude_trusted");

interface HookDefinition {
    command: string;
    matcher?: string;
}

interface HookResult {
    blocked: boolean;
    messages: string[];
    block_reason?: string;
    permission_override?: string;
}

/**
 * Load and execute hooks from .hooks.json configuration.
 *
 * The hook manager does three simple jobs:
 * - load hook definitions
 * - run matching commands for an event
 * - aggregate block / message results for the caller
 *
 * TypeScript: Class with typed properties
 * Python: class HookManager
 */
class HookManager {
    hooks: Record<string, HookDefinition[]>;
    private _sdkMode: boolean;

    constructor(configPath?: string, sdkMode: boolean = false) {
        this.hooks = {
            PreToolUse: [],
            PostToolUse: [],
            SessionStart: [],
        };
        this._sdkMode = sdkMode;
        const resolvedPath = configPath || path.join(WORKDIR, ".hooks.json");

        try {
            const configText = require("fs").readFileSync(resolvedPath, "utf-8");
            const config = JSON.parse(configText);
            for (const event of HOOK_EVENTS) {
                this.hooks[event] = (config.hooks?.[event] || []);
            }
            console.log(`[Hooks loaded from ${resolvedPath}]`);
        } catch (e: any) {
            if (e.code !== "ENOENT") {
                console.log(`[Hook config error: ${e.message}]`);
            }
            // No config file is fine -- hooks are optional
        }
    }

    /**
     * Check whether the current workspace is trusted.
     *
     * The teaching version uses a simple trust marker file.
     * In SDK mode, trust is treated as implicit.
     *
     * TypeScript: Uses fs.accessSync for simplicity in constructor context
     * Python: Path.exists() check
     */
    _checkWorkspaceTrust(): boolean {
        if (this._sdkMode) return true;
        try {
            require("fs").accessSync(TRUST_MARKER);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Execute all hooks for an event.
     *
     * Returns: { blocked: boolean, messages: string[] }
     *   - blocked: true if any hook returned exit code 1
     *   - messages: stderr content from exit-code-2 hooks (to inject)
     *
     * TypeScript: async method returning typed HookResult
     * Python: def run_hooks(self, event, context) -> dict
     */
    async runHooks(event: string, context?: Record<string, any>): Promise<HookResult> {
        const result: HookResult = { blocked: false, messages: [] };

        // Trust gate: refuse to run hooks in untrusted workspaces
        if (!this._checkWorkspaceTrust()) {
            return result;
        }

        const hooks = this.hooks[event] || [];

        for (const hookDef of hooks) {
            // Check matcher (tool name filter for PreToolUse/PostToolUse)
            const matcher = hookDef.matcher;
            if (matcher && context) {
                const toolName = context.tool_name || "";
                if (matcher !== "*" && matcher !== toolName) {
                    continue;
                }
            }

            const command = hookDef.command || "";
            if (!command) continue;

            // Build environment with hook context
            // TypeScript: Spread operator for env copy
            // Python: dict(os.environ)
            const env: Record<string, string | undefined> = { ...process.env };
            if (context) {
                env.HOOK_EVENT = event;
                env.HOOK_TOOL_NAME = context.tool_name || "";
                env.HOOK_TOOL_INPUT = JSON.stringify(
                    context.tool_input || {}
                ).slice(0, 10000);
                if ("tool_output" in context) {
                    env.HOOK_TOOL_OUTPUT = String(context.tool_output).slice(0, 10000);
                }
            }

            try {
                const { stdout, stderr } = await execAsync(command, {
                    cwd: WORKDIR,
                    env: env as Record<string, string>,
                    timeout: HOOK_TIMEOUT * 1000,
                });

                // Exit code 0: continue silently
                if (stdout.trim()) {
                    console.log(`  [hook:${event}] ${stdout.trim().slice(0, 100)}`);
                }

                // Optional structured stdout: small extension point that
                // keeps the teaching contract simple.
                try {
                    const hookOutput = JSON.parse(stdout);
                    if ("updatedInput" in hookOutput && context) {
                        context.tool_input = hookOutput.updatedInput;
                    }
                    if ("additionalContext" in hookOutput) {
                        result.messages.push(hookOutput.additionalContext);
                    }
                    if ("permissionDecision" in hookOutput) {
                        result.permission_override = hookOutput.permissionDecision;
                    }
                } catch {
                    // stdout was not JSON -- normal for simple hooks
                }
            } catch (error: any) {
                // execAsync throws on non-zero exit codes
                const exitCode = error.code || 0;
                const hookStdout = error.stdout || "";
                const hookStderr = error.stderr || "";

                if (exitCode === 1) {
                    // Block execution
                    result.blocked = true;
                    const reason = hookStderr.trim() || "Blocked by hook";
                    result.block_reason = reason;
                    console.log(`  [hook:${event}] BLOCKED: ${reason.slice(0, 200)}`);
                } else if (exitCode === 2) {
                    // Inject message
                    const msg = hookStderr.trim();
                    if (msg) {
                        result.messages.push(msg);
                        console.log(`  [hook:${event}] INJECT: ${msg.slice(0, 200)}`);
                    }
                } else if (error.killed) {
                    // Timeout
                    console.log(`  [hook:${event}] Timeout (${HOOK_TIMEOUT}s)`);
                } else {
                    // Other error
                    const errStderr = hookStderr.trim();
                    if (errStderr) {
                        console.log(`  [hook:${event}] Error: ${errStderr.slice(0, 200)}`);
                    }
                }

                // Check stdout for structured output even on non-zero exit
                try {
                    const hookOutput = JSON.parse(hookStdout);
                    if ("updatedInput" in hookOutput && context) {
                        context.tool_input = hookOutput.updatedInput;
                    }
                    if ("additionalContext" in hookOutput) {
                        result.messages.push(hookOutput.additionalContext);
                    }
                    if ("permissionDecision" in hookOutput) {
                        result.permission_override = hookOutput.permissionDecision;
                    }
                } catch {
                    // Not JSON -- ignore
                }
            }
        }

        return result;
    }
}

// -- Tool implementations (same as s02) --
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error: any) {
        if (error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },
};

/**
 * Tool definitions
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

/**
 * Message types
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`;

/**
 * The hook-aware agent loop.
 *
 * The teaching version keeps only the clearest integration points:
 * SessionStart, PreToolUse, execute tool, PostToolUse.
 *
 * TypeScript: async function with HookManager parameter
 * Python: def agent_loop(messages, hooks)
 */
async function agentLoop(
    messages: Message[],
    hooks: HookManager
): Promise<void> {
    while (true) {
        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type !== "tool_use" || !block.id || !block.name) continue;

            const toolInput = { ...(block.input as Record<string, any> || {}) };
            const ctx: Record<string, any> = {
                tool_name: block.name,
                tool_input: toolInput,
            };

            // -- PreToolUse hooks --
            const preResult = await hooks.runHooks("PreToolUse", ctx);

            // Inject hook messages into results
            for (const msg of preResult.messages) {
                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: `[Hook message]: ${msg}`,
                });
            }

            if (preResult.blocked) {
                const reason = preResult.block_reason || "Blocked by hook";
                const output = `Tool blocked by PreToolUse hook: ${reason}`;
                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
                continue;
            }

            // -- Execute tool --
            const handler = TOOL_HANDLERS[block.name];
            let output: string;
            try {
                output = handler
                    ? await handler(toolInput)
                    : `Unknown: ${block.name}`;
            } catch (error) {
                output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
            }
            console.log(`> ${block.name}: ${output.slice(0, 200)}`);

            // -- PostToolUse hooks --
            ctx.tool_output = output;
            const postResult = await hooks.runHooks("PostToolUse", ctx);

            // Inject post-hook messages
            for (const msg of postResult.messages) {
                output += `\n[Hook note]: ${msg}`;
            }

            results.push({
                type: "tool_result",
                tool_use_id: block.id,
                content: output,
            });
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    const hooks = new HookManager();

    // Fire SessionStart hooks
    await hooks.runHooks("SessionStart", { tool_name: "", tool_input: {} });

    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 8: Hook System. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms08 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history, hooks);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: persistence -- remembering across the session boundary.
// @ts-nocheck
/**
 * s09_memory_system.ts - Memory System
 *
 * This teaching version focuses on one core idea:
 * some information should survive the current conversation, but not everything
 * belongs in memory.
 *
 * Use memory for:
 *   - user preferences
 *   - repeated user feedback
 *   - project facts that are NOT obvious from the current code
 *   - pointers to external resources
 *
 * Do NOT use memory for:
 *   - code structure that can be re-read from the repo
 *   - temporary task state
 *   - secrets
 *
 * Storage layout:
 *   .memory/
 *     MEMORY.md
 *     prefer_tabs.md
 *     review_style.md
 *     incident_board.md
 *
 * Each memory is a small Markdown file with frontmatter.
 * The agent can save a memory through save_memory(), and the memory index
 * is rebuilt after each write.
 *
 * An optional "Dream" pass can later consolidate, deduplicate, and prune
 * stored memories. It is useful, but it is not the first thing readers need
 * to understand.
 *
 * Key insight: "Memory only stores cross-session information that is still
 * worth recalling later and is not easy to re-derive from the current repo."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. FILE SYSTEM OPERATIONS:
 *    - Python: Path.read_text(), Path.write_text(), Path.mkdir()
 *    - TypeScript: await fs.readFile/writeFile/mkdir (all async)
 *    - TypeScript requires async/await for every file operation
 *
 * 2. DIRECTORY SCANNING:
 *    - Python: sorted(memory_dir.glob("*.md")) for file iteration
 *    - TypeScript: await fs.readdir() with filter + sort
 *    - Both produce sorted lists of matching files
 *
 * 3. FRONTMATTER PARSING:
 *    - Python: re.match() with DOTALL flag, manual key:value parsing
 *    - TypeScript: RegExp with 's' flag (or [\\s\\S]*), same parsing logic
 *    - Both return structured objects with name/description/type/content
 *
 * 4. PID-BASED LOCKING:
 *    - Python: os.getpid(), os.kill(pid, 0) for process check
 *    - TypeScript: process.pid, process.kill(pid, 0) for same
 *    - Both use signal-0 trick to check if a process is alive
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const execAsync = promisify(exec);

const MEMORY_DIR = path.join(WORKDIR, ".memory");
const MEMORY_INDEX = path.join(MEMORY_DIR, "MEMORY.md");
const MEMORY_TYPES = ["user", "feedback", "project", "reference"] as const;
type MemoryType = (typeof MEMORY_TYPES)[number];
const MAX_INDEX_LINES = 200;

interface MemoryEntry {
    description: string;
    type: MemoryType;
    content: string;
    file: string;
}

interface ParsedFrontmatter {
    name?: string;
    description?: string;
    type?: string;
    content: string;
}

/**
 * Load, build, and save persistent memories across sessions.
 *
 * The teaching version keeps memory explicit:
 * one Markdown file per memory, plus one compact index file.
 *
 * TypeScript: Class with async methods for all file operations
 * Python: class MemoryManager with sync file operations
 */
class MemoryManager {
    memoryDir: string;
    memories: Record<string, MemoryEntry>;

    constructor(memoryDir?: string) {
        this.memoryDir = memoryDir || MEMORY_DIR;
        this.memories = {};
    }

    /**
     * Load MEMORY.md index and all individual memory files.
     *
     * TypeScript: async method using fs.readdir + fs.readFile
     * Python: sync method using Path.glob + Path.read_text
     */
    async loadAll(): Promise<void> {
        this.memories = {};
        try {
            const files = await fs.readdir(this.memoryDir);
            const mdFiles = files
                .filter((f) => f.endsWith(".md") && f !== "MEMORY.md")
                .sort();

            for (const mdFile of mdFiles) {
                const filePath = path.join(this.memoryDir, mdFile);
                const text = await fs.readFile(filePath, "utf-8");
                const parsed = this._parseFrontmatter(text);
                if (parsed) {
                    const name = parsed.name || path.basename(mdFile, ".md");
                    this.memories[name] = {
                        description: parsed.description || "",
                        type: (parsed.type as MemoryType) || "project",
                        content: parsed.content || "",
                        file: mdFile,
                    };
                }
            }

            const count = Object.keys(this.memories).length;
            if (count > 0) {
                console.log(`[Memory loaded: ${count} memories from ${this.memoryDir}]`);
            }
        } catch {
            // Directory does not exist yet -- that is fine
        }
    }

    /**
     * Build a memory section for injection into the system prompt.
     *
     * TypeScript: Returns string with grouped memory content
     * Python: def load_memory_prompt(self) -> str
     */
    loadMemoryPrompt(): string {
        if (Object.keys(this.memories).length === 0) return "";

        const sections: string[] = [];
        sections.push("# Memories (persistent across sessions)");
        sections.push("");

        // Group by type for readability
        for (const memType of MEMORY_TYPES) {
            const typed = Object.entries(this.memories)
                .filter(([_, mem]) => mem.type === memType);
            if (typed.length === 0) continue;

            sections.push(`## [${memType}]`);
            for (const [name, mem] of typed) {
                sections.push(`### ${name}: ${mem.description}`);
                if (mem.content.trim()) {
                    sections.push(mem.content.trim());
                }
                sections.push("");
            }
        }

        return sections.join("\n");
    }

    /**
     * Save a memory to disk and update the index.
     *
     * Returns a status message.
     *
     * TypeScript: async method with fs.writeFile
     * Python: def save_memory(self, name, description, mem_type, content) -> str
     */
    async saveMemory(
        name: string,
        description: string,
        memType: string,
        content: string
    ): Promise<string> {
        if (!(MEMORY_TYPES as readonly string[]).includes(memType)) {
            return `Error: type must be one of ${MEMORY_TYPES.join(", ")}`;
        }

        // Sanitize name for filename
        // TypeScript: String replacement with regex
        // Python: re.sub(r"[^a-zA-Z0-9_-]", "_", name.lower())
        const safeName = name.toLowerCase().replace(/[^a-zA-Z0-9_-]/g, "_");
        if (!safeName) {
            return "Error: invalid memory name";
        }

        await fs.mkdir(this.memoryDir, { recursive: true });

        // Write individual memory file with frontmatter
        const frontmatter =
            `---\n` +
            `name: ${name}\n` +
            `description: ${description}\n` +
            `type: ${memType}\n` +
            `---\n` +
            `${content}\n`;

        const fileName = `${safeName}.md`;
        const filePath = path.join(this.memoryDir, fileName);
        await fs.writeFile(filePath, frontmatter, "utf-8");

        // Update in-memory store
        this.memories[name] = {
            description,
            type: memType as MemoryType,
            content,
            file: fileName,
        };

        // Rebuild MEMORY.md index
        await this._rebuildIndex();

        const relativePath = path.relative(WORKDIR, filePath);
        return `Saved memory '${name}' [${memType}] to ${relativePath}`;
    }

    /**
     * Rebuild MEMORY.md from current in-memory state, capped at 200 lines.
     *
     * TypeScript: async method with fs.writeFile
     * Python: def _rebuild_index(self)
     */
    async _rebuildIndex(): Promise<void> {
        const lines: string[] = ["# Memory Index", ""];

        for (const [name, mem] of Object.entries(this.memories)) {
            lines.push(`- ${name}: ${mem.description} [${mem.type}]`);
            if (lines.length >= MAX_INDEX_LINES) {
                lines.push(`... (truncated at ${MAX_INDEX_LINES} lines)`);
                break;
            }
        }

        await fs.mkdir(this.memoryDir, { recursive: true });
        await fs.writeFile(MEMORY_INDEX, lines.join("\n") + "\n", "utf-8");
    }

    /**
     * Parse --- delimited frontmatter + body content.
     *
     * TypeScript: RegExp with [\\s\\S]* for DOTALL equivalent
     * Python: re.match(r"^---\s*\n(.*?)\n---\s*\n(.*)", text, re.DOTALL)
     */
    _parseFrontmatter(text: string): ParsedFrontmatter | null {
        const match = text.match(/^---\s*\n([\s\S]*?)\n---\s*\n([\s\S]*)/);
        if (!match) return null;

        const header = match[1];
        const body = match[2];
        const result: ParsedFrontmatter = { content: body.trim() };

        for (const line of header.split("\n")) {
            const colonIdx = line.indexOf(":");
            if (colonIdx !== -1) {
                const key = line.slice(0, colonIdx).trim();
                const value = line.slice(colonIdx + 1).trim();
                (result as any)[key] = value;
            }
        }

        return result;
    }
}

/**
 * Auto-consolidation of memories between sessions ("Dream").
 *
 * This is an optional later-stage feature. Its job is to prevent the memory
 * store from growing into a noisy pile by merging, deduplicating, and
 * pruning entries over time.
 *
 * TypeScript: Class with async methods and process.pid for lock file
 * Python: class DreamConsolidator with os.getpid()
 */
class DreamConsolidator {
    static COOLDOWN_SECONDS = 86400;       // 24 hours between consolidations
    static SCAN_THROTTLE_SECONDS = 600;    // 10 minutes between scan attempts
    static MIN_SESSION_COUNT = 5;          // need enough data to consolidate
    static LOCK_STALE_SECONDS = 3600;      // PID lock considered stale after 1 hour

    static PHASES = [
        "Orient: scan MEMORY.md index for structure and categories",
        "Gather: read individual memory files for full content",
        "Consolidate: merge related memories, remove stale entries",
        "Prune: enforce 200-line limit on MEMORY.md index",
    ];

    memoryDir: string;
    lockFile: string;
    enabled: boolean;
    mode: string;
    lastConsolidationTime: number;
    lastScanTime: number;
    sessionCount: number;

    constructor(memoryDir?: string) {
        this.memoryDir = memoryDir || MEMORY_DIR;
        this.lockFile = path.join(this.memoryDir, ".dream_lock");
        this.enabled = true;
        this.mode = "default";
        this.lastConsolidationTime = 0;
        this.lastScanTime = 0;
        this.sessionCount = 0;
    }

    /**
     * Check 7 gates in sequence. All must pass.
     * Returns [canRun, reason] where reason explains the first failed gate.
     *
     * TypeScript: Returns [boolean, string] tuple
     * Python: Returns tuple[bool, str]
     */
    shouldConsolidate(): [boolean, string] {
        const now = Date.now() / 1000; // seconds

        // Gate 1: enabled flag
        if (!this.enabled) {
            return [false, "Gate 1: consolidation is disabled"];
        }

        // Gate 2: memory directory exists and has memory files
        // Note: synchronous check for gate validation; full async in consolidate()
        try {
            const files = require("fs").readdirSync(this.memoryDir) as string[];
            const memoryFiles = files.filter(
                (f: string) => f.endsWith(".md") && f !== "MEMORY.md"
            );
            if (memoryFiles.length === 0) {
                return [false, "Gate 2: no memory files found"];
            }
        } catch {
            return [false, "Gate 2: memory directory does not exist"];
        }

        // Gate 3: not in plan mode (only consolidate in active modes)
        if (this.mode === "plan") {
            return [false, "Gate 3: plan mode does not allow consolidation"];
        }

        // Gate 4: 24-hour cooldown since last consolidation
        const timeSinceLast = now - this.lastConsolidationTime;
        if (timeSinceLast < DreamConsolidator.COOLDOWN_SECONDS) {
            const remaining = Math.floor(DreamConsolidator.COOLDOWN_SECONDS - timeSinceLast);
            return [false, `Gate 4: cooldown active, ${remaining}s remaining`];
        }

        // Gate 5: 10-minute throttle since last scan attempt
        const timeSinceScan = now - this.lastScanTime;
        if (timeSinceScan < DreamConsolidator.SCAN_THROTTLE_SECONDS) {
            const remaining = Math.floor(DreamConsolidator.SCAN_THROTTLE_SECONDS - timeSinceScan);
            return [false, `Gate 5: scan throttle active, ${remaining}s remaining`];
        }

        // Gate 6: need at least 5 sessions worth of data
        if (this.sessionCount < DreamConsolidator.MIN_SESSION_COUNT) {
            return [false, `Gate 6: only ${this.sessionCount} sessions, need ${DreamConsolidator.MIN_SESSION_COUNT}`];
        }

        // Gate 7: no active lock file (check PID staleness)
        if (!this._acquireLock()) {
            return [false, "Gate 7: lock held by another process"];
        }

        return [true, "All 7 gates passed"];
    }

    /**
     * Run the 4-phase consolidation process.
     *
     * The teaching version returns phase descriptions to make the flow
     * visible without requiring an extra LLM pass here.
     *
     * TypeScript: Returns string[] of completed phases
     * Python: def consolidate(self) -> list[str]
     */
    async consolidate(): Promise<string[]> {
        const [canRun, reason] = this.shouldConsolidate();
        if (!canRun) {
            console.log(`[Dream] Cannot consolidate: ${reason}`);
            return [];
        }

        console.log("[Dream] Starting consolidation...");
        this.lastScanTime = Date.now() / 1000;

        const completedPhases: string[] = [];
        DreamConsolidator.PHASES.forEach((phase, i) => {
            console.log(`[Dream] Phase ${i + 1}/4: ${phase}`);
            completedPhases.push(phase);
        });

        this.lastConsolidationTime = Date.now() / 1000;
        this._releaseLock();
        console.log(`[Dream] Consolidation complete: ${completedPhases.length} phases executed`);
        return completedPhases;
    }

    /**
     * Acquire a PID-based lock file. Returns false if locked by another
     * live process. Stale locks (older than LOCK_STALE_SECONDS) are removed.
     *
     * TypeScript: Uses process.pid and process.kill(pid, 0)
     * Python: Uses os.getpid() and os.kill(pid, 0)
     */
    _acquireLock(): boolean {
        const now = Date.now() / 1000;

        try {
            const lockData = require("fs").readFileSync(this.lockFile, "utf-8").trim();
            const colonIdx = lockData.indexOf(":");
            if (colonIdx === -1) throw new Error("corrupted");

            const pid = parseInt(lockData.slice(0, colonIdx), 10);
            const lockTime = parseFloat(lockData.slice(colonIdx + 1));

            // Check if lock is stale
            if ((now - lockTime) > DreamConsolidator.LOCK_STALE_SECONDS) {
                console.log(`[Dream] Removing stale lock from PID ${pid}`);
                require("fs").unlinkSync(this.lockFile);
            } else {
                // Check if owning process is still alive
                try {
                    process.kill(pid, 0);
                    return false; // process alive, lock is valid
                } catch {
                    console.log(`[Dream] Removing lock from dead PID ${pid}`);
                    require("fs").unlinkSync(this.lockFile);
                }
            }
        } catch (e: any) {
            if (e.code !== "ENOENT" && e.message !== "corrupted") {
                // Corrupted lock file, remove it
                try {
                    require("fs").unlinkSync(this.lockFile);
                } catch { /* ignore */ }
            }
            // ENOENT means no lock file -- proceed
        }

        // Write new lock
        try {
            require("fs").mkdirSync(this.memoryDir, { recursive: true });
            require("fs").writeFileSync(this.lockFile, `${process.pid}:${now}`);
            return true;
        } catch {
            return false;
        }
    }

    /**
     * Release the lock file if we own it.
     *
     * TypeScript: Synchronous unlink for lock release
     * Python: def _release_lock(self)
     */
    _releaseLock(): void {
        try {
            const lockData = require("fs").readFileSync(this.lockFile, "utf-8").trim();
            const pidStr = lockData.split(":")[0];
            if (parseInt(pidStr, 10) === process.pid) {
                require("fs").unlinkSync(this.lockFile);
            }
        } catch {
            // Lock file gone or corrupted -- nothing to release
        }
    }
}

// -- Tool implementations --
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error: any) {
        if (error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

// Global memory manager
const memoryMgr = new MemoryManager();

async function runSaveMemory(
    name: string,
    description: string,
    memType: string,
    content: string
): Promise<string> {
    return memoryMgr.saveMemory(name, description, memType, content);
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: Now includes save_memory handler!
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },

    save_memory: async (input) => {
        const name = input.name as string;
        const description = input.description as string;
        const memType = input.type as string;
        const content = input.content as string;
        return runSaveMemory(name, description, memType, content);
    },
};

/**
 * Tool definitions - now includes save_memory!
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
    {
        name: "save_memory",
        description: "Save a persistent memory that survives across sessions.",
        input_schema: {
            type: "object" as const,
            properties: {
                name: {
                    type: "string",
                    description: "Short identifier (e.g. prefer_tabs, db_schema)",
                },
                description: {
                    type: "string",
                    description: "One-line summary of what this memory captures",
                },
                type: {
                    type: "string",
                    description:
                        "user=preferences, feedback=corrections, project=non-obvious project conventions or decision reasons, reference=external resource pointers",
                },
                content: {
                    type: "string",
                    description: "Full memory content (multi-line OK)",
                },
            },
            required: ["name", "description", "type", "content"] as const,
        },
    },
];

/**
 * Message types
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

const MEMORY_GUIDANCE = `
When to save memories:
- User states a preference ("I like tabs", "always use pytest") -> type: user
- User corrects you ("don't do X", "that was wrong because...") -> type: feedback
- You learn a project fact that is not easy to infer from current code alone
  (for example: a rule exists because of compliance, or a legacy module must
  stay untouched for business reasons) -> type: project
- You learn where an external resource lives (ticket board, dashboard, docs URL)
  -> type: reference

When NOT to save:
- Anything easily derivable from code (function signatures, file structure, directory layout)
- Temporary task state (current branch, open PR numbers, current TODOs)
- Secrets or credentials (API keys, passwords)
`;

/**
 * Assemble system prompt with memory content included.
 *
 * TypeScript: Returns string with memory section injected
 * Python: def build_system_prompt() -> str
 */
function buildSystemPrompt(): string {
    const parts = [`You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`];

    // Inject memory content if available
    const memorySection = memoryMgr.loadMemoryPrompt();
    if (memorySection) {
        parts.push(memorySection);
    }

    parts.push(MEMORY_GUIDANCE);
    return parts.join("\n\n");
}

/**
 * Agent loop with memory-aware system prompt.
 *
 * The system prompt is rebuilt each call so newly saved memories
 * are visible in the next LLM turn within the same session.
 *
 * TypeScript: async function rebuilding system prompt each call
 * Python: def agent_loop(messages)
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        // Rebuild system prompt each call so new memories are visible
        const system = buildSystemPrompt();

        const response = await client.messages.create({
            model: MODEL,
            system: system,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type !== "tool_use" || !block.id || !block.name) continue;

            const handler = TOOL_HANDLERS[block.name];
            let output: string;
            try {
                output = handler
                    ? await handler(block.input || {})
                    : `Unknown: ${block.name}`;
            } catch (error) {
                output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
            }
            console.log(`> ${block.name}: ${output.slice(0, 200)}`);

            results.push({
                type: "tool_result",
                tool_use_id: block.id,
                content: output,
            });
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    // Load existing memories at session start
    await memoryMgr.loadAll();
    const memCount = Object.keys(memoryMgr.memories).length;
    if (memCount) {
        console.log(`[${memCount} memories loaded into context]`);
    } else {
        console.log("[No existing memories. The agent can create them with save_memory.]");
    }

    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 9: Memory System. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms09 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            // /memories command to list current memories
            if (query.trim() === "/memories") {
                if (Object.keys(memoryMgr.memories).length > 0) {
                    for (const [name, mem] of Object.entries(memoryMgr.memories)) {
                        console.log(`  [${mem.type}] ${name}: ${mem.description}`);
                    }
                } else {
                    console.log("  (no memories)");
                }
                continue;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: assembly -- the system prompt is a pipeline, not a string.
// @ts-nocheck
/**
 * s10_system_prompt.ts - System Prompt Construction
 *
 * This chapter teaches one core idea:
 * the system prompt should be assembled from clear sections, not written as one
 * giant hardcoded blob.
 *
 * Teaching pipeline:
 *   1. core instructions
 *   2. tool listing
 *   3. skill metadata
 *   4. memory section
 *   5. CLAUDE.md chain
 *   6. dynamic context
 *
 * The builder keeps stable information separate from information that changes
 * often. A simple DYNAMIC_BOUNDARY marker makes that split visible.
 *
 * Per-turn reminders are even more dynamic. They are better injected as a
 * separate user-role system reminder than mixed blindly into the stable prompt.
 *
 * Key insight: "Prompt construction is a pipeline with boundaries, not one
 * big string."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. FILE SYSTEM OPERATIONS:
 *    - Python: pathlib.Path with exists(), read_text(), iterdir(), glob()
 *    - TypeScript: fs.promises with readFile(), readdir(), stat()
 *    - TypeScript requires async/await for all file operations
 *
 * 2. REGEX MATCHING:
 *    - Python: re.match(r"^---\n(.*?)\n---", text, re.DOTALL)
 *    - TypeScript: text.match(/^---\s*\n([\s\S]*?)\n---/, text)
 *    - TypeScript uses [\s\S] instead of re.DOTALL flag
 *
 * 3. CLASS CONSTRUCTION:
 *    - Python: class with __init__, self reference
 *    - TypeScript: class with constructor, this reference
 *    - TypeScript methods need explicit return types
 *
 * 4. OS INTEROP:
 *    - Python: os.uname().sysname
 *    - TypeScript: os.platform() or process.platform
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import os from "os";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const DYNAMIC_BOUNDARY = "=== DYNAMIC_BOUNDARY ===";

/**
 * SystemPromptBuilder - Assemble the system prompt from independent sections.
 *
 * The teaching goal here is clarity:
 * each section has one source and one responsibility.
 *
 * That makes the prompt easier to reason about, easier to test, and easier
 * to evolve as the agent grows new capabilities.
 *
 * TypeScript: class with typed properties and methods
 * Python: class SystemPromptBuilder with __init__
 */
class SystemPromptBuilder {
    private workdir: string;
    private tools: any[];
    private skillsDir: string;
    private memoryDir: string;

    constructor(workdir?: string, tools?: any[]) {
        this.workdir = workdir || WORKDIR;
        this.tools = tools || [];
        this.skillsDir = path.join(this.workdir, "skills");
        this.memoryDir = path.join(this.workdir, ".memory");
    }

    // -- Section 1: Core instructions --
    _buildCore(): string {
        return (
            `You are a coding agent operating in ${this.workdir}.\n` +
            "Use the provided tools to explore, read, write, and edit files.\n" +
            "Always verify before assuming. Prefer reading files over guessing."
        );
    }

    // -- Section 2: Tool listings --
    _buildToolListing(): string {
        if (!this.tools.length) {
            return "";
        }
        const lines = ["# Available tools"];
        for (const tool of this.tools) {
            const props = tool.input_schema?.properties || {};
            const params = Object.keys(props).join(", ");
            lines.push(`- ${tool.name}(${params}): ${tool.description}`);
        }
        return lines.join("\n");
    }

    // -- Section 3: Skill metadata (layer 1 from s05 concept) --
    async _buildSkillListing(): Promise<string> {
        try {
            const entries = await fs.readdir(this.skillsDir, { withFileTypes: true });
            const skills: string[] = [];

            for (const entry of entries.sort((a, b) => a.name.localeCompare(b.name))) {
                if (!entry.isDirectory()) continue;
                const skillMdPath = path.join(this.skillsDir, entry.name, "SKILL.md");
                let text: string;
                try {
                    text = await fs.readFile(skillMdPath, "utf-8");
                } catch {
                    continue;
                }

                // Parse frontmatter for name + description
                const match = text.match(/^---\s*\n([\s\S]*?)\n---/);
                if (!match) continue;

                const meta: Record<string, string> = {};
                for (const line of match[1].split("\n")) {
                    const colonIdx = line.indexOf(":");
                    if (colonIdx !== -1) {
                        const k = line.slice(0, colonIdx).trim();
                        const v = line.slice(colonIdx + 1).trim();
                        meta[k] = v;
                    }
                }
                const name = meta.name || entry.name;
                const desc = meta.description || "";
                skills.push(`- ${name}: ${desc}`);
            }

            if (!skills.length) return "";
            return "# Available skills\n" + skills.join("\n");
        } catch {
            return "";
        }
    }

    // -- Section 4: Memory content --
    async _buildMemorySection(): Promise<string> {
        try {
            const files = await fs.readdir(this.memoryDir);
            const mdFiles = files
                .filter((f) => f.endsWith(".md") && f !== "MEMORY.md")
                .sort();
            const memories: string[] = [];

            for (const fileName of mdFiles) {
                const mdFilePath = path.join(this.memoryDir, fileName);
                const text = await fs.readFile(mdFilePath, "utf-8");
                const match = text.match(/^---\s*\n([\s\S]*?)\n---\s*\n([\s\S]*)/);
                if (!match) continue;

                const header = match[1];
                const body = match[2].trim();
                const meta: Record<string, string> = {};
                for (const line of header.split("\n")) {
                    const colonIdx = line.indexOf(":");
                    if (colonIdx !== -1) {
                        const k = line.slice(0, colonIdx).trim();
                        const v = line.slice(colonIdx + 1).trim();
                        meta[k] = v;
                    }
                }
                const name = meta.name || path.basename(fileName, ".md");
                const memType = meta.type || "project";
                const desc = meta.description || "";
                memories.push(`[${memType}] ${name}: ${desc}\n${body}`);
            }

            if (!memories.length) return "";
            return "# Memories (persistent)\n\n" + memories.join("\n\n");
        } catch {
            return "";
        }
    }

    // -- Section 5: CLAUDE.md chain --
    async _buildClaudeMd(): Promise<string> {
        /**
         * Load CLAUDE.md files in priority order (all are included):
         * 1. ~/.claude/CLAUDE.md (user-global instructions)
         * 2. <project-root>/CLAUDE.md (project instructions)
         * 3. <current-subdir>/CLAUDE.md (directory-specific instructions)
         */
        const sources: [string, string][] = [];

        // User-global
        const userClaude = path.join(os.homedir(), ".claude", "CLAUDE.md");
        try {
            const content = await fs.readFile(userClaude, "utf-8");
            sources.push(["user global (~/.claude/CLAUDE.md)", content]);
        } catch { /* file doesn't exist */ }

        // Project root
        const projectClaude = path.join(this.workdir, "CLAUDE.md");
        try {
            const content = await fs.readFile(projectClaude, "utf-8");
            sources.push(["project root (CLAUDE.md)", content]);
        } catch { /* file doesn't exist */ }

        // Subdirectory -- in real CC, this walks from cwd up to project root
        // Teaching: check cwd if different from workdir
        const cwd = process.cwd();
        if (cwd !== this.workdir) {
            const subdirClaude = path.join(cwd, "CLAUDE.md");
            try {
                const content = await fs.readFile(subdirClaude, "utf-8");
                const dirName = path.basename(cwd);
                sources.push([`subdir (${dirName}/CLAUDE.md)`, content]);
            } catch { /* file doesn't exist */ }
        }

        if (!sources.length) return "";
        const parts = ["# CLAUDE.md instructions"];
        for (const [label, content] of sources) {
            parts.push(`## From ${label}`);
            parts.push(content.trim());
        }
        return parts.join("\n\n");
    }

    // -- Section 6: Dynamic context --
    _buildDynamicContext(): string {
        const lines = [
            `Current date: ${new Date().toISOString().split("T")[0]}`,
            `Working directory: ${this.workdir}`,
            `Model: ${MODEL}`,
            `Platform: ${process.platform}`,
        ];
        return "# Dynamic context\n" + lines.join("\n");
    }

    // -- Assemble all sections --
    async build(): Promise<string> {
        /**
         * Assemble the full system prompt from all sections.
         *
         * Static sections (1-5) are separated from dynamic (6) by
         * the DYNAMIC_BOUNDARY marker. In real CC, the static prefix
         * is cached across turns to save prompt tokens.
         */
        const sections: string[] = [];

        const core = this._buildCore();
        if (core) sections.push(core);

        const tools = this._buildToolListing();
        if (tools) sections.push(tools);

        const skills = await this._buildSkillListing();
        if (skills) sections.push(skills);

        const memory = await this._buildMemorySection();
        if (memory) sections.push(memory);

        const claudeMd = await this._buildClaudeMd();
        if (claudeMd) sections.push(claudeMd);

        // Static/dynamic boundary
        sections.push(DYNAMIC_BOUNDARY);

        const dynamic = this._buildDynamicContext();
        if (dynamic) sections.push(dynamic);

        return sections.join("\n\n");
    }
}

/**
 * Build a system-reminder user message for per-turn dynamic content.
 *
 * The teaching version keeps reminders outside the stable system prompt so
 * short-lived context does not get mixed into the long-lived instructions.
 *
 * TypeScript: Returns Message | null
 * Python: def build_system_reminder(extra: str = None) -> dict
 */
function buildSystemReminder(extra?: string): Message | null {
    const parts: string[] = [];
    if (extra) parts.push(extra);
    if (!parts.length) return null;
    const content = "<system-reminder>\n" + parts.join("\n") + "\n</system-reminder>";
    return { role: "user", content };
}

/**
 * Safe path validation
 * TypeScript: Returns string (absolute path)
 * Python: Returns Path object
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

const execAsync = promisify(exec);

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },
};

/**
 * Tool definitions for Anthropic API
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

// Global prompt builder
const promptBuilder = new SystemPromptBuilder(WORKDIR, TOOLS);

/**
 * Agent loop with assembled system prompt.
 *
 * The system prompt is rebuilt each iteration. In real CC, the static
 * prefix is cached and only the dynamic suffix changes per turn.
 *
 * TypeScript: async function
 * Python: def agent_loop(messages: list)
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        // Rebuild system prompt each iteration
        // TypeScript: await async build method
        // Python: system = prompt_builder.build()
        const system = await promptBuilder.build();

        const response = await client.messages.create({
            model: MODEL,
            system: system,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    try {
                        output = await handler(block.input);
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    // Show the assembled prompt at startup for educational purposes
    const fullPrompt = await promptBuilder.build();
    const sectionCount = fullPrompt.split("\n").filter((l) => l.startsWith("# ")).length;
    console.log(`[System prompt assembled: ${fullPrompt.length} chars, ~${sectionCount} sections]`);

    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 10: System Prompt Construction. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms10 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            // /prompt command shows the full assembled prompt
            if (query.trim() === "/prompt") {
                console.log("--- System Prompt ---");
                console.log(await promptBuilder.build());
                console.log("--- End ---");
                continue;
            }

            // /sections command shows just the section headings
            if (query.trim() === "/sections") {
                const prompt = await promptBuilder.build();
                for (const line of prompt.split("\n")) {
                    if (line.startsWith("# ") || line === DYNAMIC_BOUNDARY) {
                        console.log(`  ${line}`);
                    }
                }
                continue;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: resilience -- a robust agent recovers instead of crashing.
// @ts-nocheck
/**
 * s11_error_recovery.ts - Error Recovery
 *
 * Teaching demo of three recovery paths:
 *
 * - continue when output is truncated
 * - compact when context grows too large
 * - back off when transport errors are temporary
 *
 *     LLM response
 *          |
 *          v
 *     [Check stop_reason]
 *          |
 *          +-- "max_tokens" ----> [Strategy 1: max_output_tokens recovery]
 *          |                       Inject continuation message:
 *          |                       "Output limit hit. Continue directly."
 *          |                       Retry up to MAX_RECOVERY_ATTEMPTS (3).
 *          |                       Counter: max_output_recovery_count
 *          |
 *          +-- API error -------> [Check error type]
 *          |                       |
 *          |                       +-- prompt_too_long --> [Strategy 2: compact + retry]
 *          |                       |   Trigger auto_compact (LLM summary).
 *          |                       |   Replace history with summary.
 *          |                       |   Retry the turn.
 *          |                       |
 *          |                       +-- connection/rate --> [Strategy 3: backoff retry]
 *          |                           Exponential backoff: base * 2^attempt + jitter
 *          |                           Up to 3 retries.
 *          |
 *          +-- "end_turn" -----> [Normal exit]
 *
 *     Recovery priority (first match wins):
 *     1. max_tokens -> inject continuation, retry
 *     2. prompt_too_long -> compact, retry
 *     3. connection error -> backoff, retry
 *     4. all retries exhausted -> fail gracefully
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. ERROR HANDLING:
 *    - Python: except APIError as e for Anthropic errors
 *    - TypeScript: catch with err instanceof APIError
 *    - TypeScript needs import { APIError } from "@anthropic-ai/sdk"
 *
 * 2. SLEEP/DELAY:
 *    - Python: time.sleep(delay) - synchronous blocking
 *    - TypeScript: await new Promise(resolve => setTimeout(resolve, delay * 1000))
 *    - TypeScript requires async approach with Promise-wrapped setTimeout
 *
 * 3. ARRAY MUTATION:
 *    - Python: messages[:] = auto_compact(messages) - in-place replacement
 *    - TypeScript: messages.splice(0, messages.length, ...autoCompact(messages))
 *    - TypeScript array mutation is explicit
 *
 * 4. RANDOM:
 *    - Python: random.uniform(0, 1) for jitter
 *    - TypeScript: Math.random() for jitter
 */

import Anthropic, { APIError } from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

// Recovery constants
const MAX_RECOVERY_ATTEMPTS = 3;
const BACKOFF_BASE_DELAY = 1.0;  // seconds
const BACKOFF_MAX_DELAY = 30.0;  // seconds
const TOKEN_THRESHOLD = 50000;   // chars / 4 ~ tokens for compact trigger

const CONTINUATION_MESSAGE = (
    "Output limit hit. Continue directly from where you stopped -- " +
    "no recap, no repetition. Pick up mid-sentence if needed."
);

/**
 * Rough token estimate: ~4 chars per token.
 * TypeScript: JSON.stringify with replacer, Math.floor
 * Python: len(json.dumps(messages, default=str)) // 4
 */
function estimateTokens(messages: Message[]): number {
    const jsonString = JSON.stringify(messages, (_, value) => {
        if (typeof value === "object" && value !== null) {
            if ("type" in value && "text" in value) {
                return { type: value.type, text: value.text };
            }
        }
        return value;
    });
    return Math.floor(jsonString.length / 4);
}

/**
 * Compress conversation history into a short continuation summary.
 *
 * TypeScript: async function returning new Message array
 * Python: def auto_compact(messages: list) -> list
 */
async function autoCompact(messages: Message[]): Promise<Message[]> {
    const conversationText = JSON.stringify(
        messages,
        (_, value) => {
            if (typeof value === "object" && value !== null) {
                if ("type" in value) {
                    return value;
                }
            }
            return value;
        }
    ).slice(0, 80000);

    const prompt = (
        "Summarize this conversation for continuity. Include:\n" +
        "1) Task overview and success criteria\n" +
        "2) Current state: completed work, files touched\n" +
        "3) Key decisions and failed approaches\n" +
        "4) Remaining next steps\n" +
        "Be concise but preserve critical details.\n\n" +
        conversationText
    );

    let summary: string;
    try {
        const response = await client.messages.create({
            model: MODEL,
            messages: [{ role: "user", content: prompt }],
            max_tokens: 4000,
        });
        // Collect text from all text blocks
        summary = response.content
            .filter((block: any) => block.type === "text")
            .map((block: any) => block.text)
            .join("\n")
            .trim();
    } catch (error) {
        summary = `(compact failed: ${error instanceof Error ? error.message : "Unknown error"}). Previous context lost.`;
    }

    const continuation = (
        "This session continues from a previous conversation that was compacted. " +
        `Summary of prior context:\n\n${summary}\n\n` +
        "Continue from where we left off without re-asking the user."
    );

    return [{ role: "user", content: continuation }];
}

/**
 * Exponential backoff with jitter: base * 2^attempt + random(0, 1).
 *
 * TypeScript: Math.random() returns [0, 1)
 * Python: random.uniform(0, 1) returns [0, 1)
 */
function backoffDelay(attempt: number): number {
    const delay = Math.min(BACKOFF_BASE_DELAY * Math.pow(2, attempt), BACKOFF_MAX_DELAY);
    const jitter = Math.random();
    return delay + jitter;
}

/**
 * Sleep helper for async delay.
 * TypeScript: Promise-wrapped setTimeout
 * Python: time.sleep(delay) (synchronous)
 */
function sleep(ms: number): Promise<void> {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

/**
 * Safe path validation
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

const execAsync = promisify(exec);

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },
};

/**
 * Tool definitions for Anthropic API
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
];

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.`;

/**
 * Error-recovering agent loop with three paths:
 *
 * 1. continue after max_tokens
 * 2. compact after prompt-too-long
 * 3. back off after transient transport failure
 *
 * TypeScript: async function with try/catch error handling
 * Python: def agent_loop(messages: list)
 *
 * Key differences:
 * - TypeScript uses err instanceof APIError for Anthropic SDK errors
 * - TypeScript uses err instanceof Error for connection errors
 * - Sleep is await-based (non-blocking) instead of time.sleep()
 * - Array mutation uses splice for in-place replacement
 */
async function agentLoop(messages: Message[]): Promise<void> {
    let maxOutputRecoveryCount = 0;

    while (true) {
        // -- Attempt the API call with connection retry --
        let response: any = null;

        for (let attempt = 0; attempt <= MAX_RECOVERY_ATTEMPTS; attempt++) {
            try {
                response = await client.messages.create({
                    model: MODEL,
                    system: SYSTEM,
                    messages: messages,
                    tools: TOOLS,
                    max_tokens: 8000,
                });
                break; // success

            } catch (err) {
                // Strategy 2: prompt_too_long -> compact and retry
                if (err instanceof APIError) {
                    const errorBody = String(err).toLowerCase();

                    if (
                        errorBody.includes("overlong_prompt") ||
                        (errorBody.includes("prompt") && errorBody.includes("long"))
                    ) {
                        console.log(`[Recovery] Prompt too long. Compacting... (attempt ${attempt + 1})`);
                        const compacted = await autoCompact(messages);
                        messages.splice(0, messages.length, ...compacted);
                        continue;
                    }

                    // Strategy 3: connection/rate errors -> backoff
                    if (attempt < MAX_RECOVERY_ATTEMPTS) {
                        const delay = backoffDelay(attempt);
                        console.log(
                            `[Recovery] API error: ${err}. ` +
                            `Retrying in ${delay.toFixed(1)}s (attempt ${attempt + 1}/${MAX_RECOVERY_ATTEMPTS})`
                        );
                        await sleep(delay * 1000);
                        continue;
                    }

                    // All retries exhausted
                    console.log(`[Error] API call failed after ${MAX_RECOVERY_ATTEMPTS} retries: ${err}`);
                    return;
                }

                // Strategy 3: network-level errors -> backoff
                // TypeScript: err instanceof Error for connection errors
                // Python: except (ConnectionError, TimeoutError, OSError) as e
                if (err instanceof Error) {
                    if (attempt < MAX_RECOVERY_ATTEMPTS) {
                        const delay = backoffDelay(attempt);
                        console.log(
                            `[Recovery] Connection error: ${err.message}. ` +
                            `Retrying in ${delay.toFixed(1)}s (attempt ${attempt + 1}/${MAX_RECOVERY_ATTEMPTS})`
                        );
                        await sleep(delay * 1000);
                        continue;
                    }

                    console.log(`[Error] Connection failed after ${MAX_RECOVERY_ATTEMPTS} retries: ${err.message}`);
                    return;
                }

                // Unknown error type
                console.log(`[Error] Unexpected error: ${err}`);
                return;
            }
        }

        if (response === null) {
            console.log("[Error] No response received.");
            return;
        }

        messages.push({
            role: "assistant",
            content: response.content,
        });

        // -- Strategy 1: max_tokens recovery --
        if (response.stop_reason === "max_tokens") {
            maxOutputRecoveryCount++;
            if (maxOutputRecoveryCount <= MAX_RECOVERY_ATTEMPTS) {
                console.log(
                    `[Recovery] max_tokens hit ` +
                    `(${maxOutputRecoveryCount}/${MAX_RECOVERY_ATTEMPTS}). ` +
                    "Injecting continuation..."
                );
                messages.push({ role: "user", content: CONTINUATION_MESSAGE });
                continue; // retry the loop
            } else {
                console.log(
                    `[Error] max_tokens recovery exhausted ` +
                    `(${MAX_RECOVERY_ATTEMPTS} attempts). Stopping.`
                );
                return;
            }
        }

        // Reset max_tokens counter on successful non-max_tokens response
        maxOutputRecoveryCount = 0;

        // -- Normal end_turn: no tool use requested --
        if (response.stop_reason !== "tool_use") {
            return;
        }

        // -- Process tool calls --
        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    try {
                        output = await handler(block.input);
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });

        // Check if we should auto-compact (proactive, not just reactive)
        if (estimateTokens(messages) > TOKEN_THRESHOLD) {
            console.log("[Recovery] Token estimate exceeds threshold. Auto-compacting...");
            const compacted = await autoCompact(messages);
            messages.splice(0, messages.length, ...compacted);
        }
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    console.log("[Error recovery enabled: max_tokens / prompt_too_long / connection backoff]");

    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 11: Error Recovery. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms11 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: persistent goals -- task graph that survives beyond single conversations.
// @ts-nocheck
/**
 * s12_task_system.ts - Tasks
 *
 * Tasks persist as JSON files in .tasks/ so they survive context compression.
 * Each task has a dependency graph (blockedBy/blocks).
 *
 *     .tasks/
 *       task_1.json  {"id":1, "subject":"...", "status":"completed", ...}
 *       task_2.json  {"id":2, "blockedBy":[1], "status":"pending", ...}
 *       task_3.json  {"id":3, "blockedBy":[2], "blocks":[], ...}
 *
 *     Dependency resolution:
 *     +----------+     +----------+     +----------+
 *     | task 1   | --> | task 2   | --> | task 3   |
 *     | complete |     | blocked  |     | blocked  |
 *     +----------+     +----------+     +----------+
 *          |                ^
 *          +--- completing task 1 removes it from task 2's blockedBy
 *
 * Key insight: "State that survives compression -- because it's outside the conversation."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. FILE OPERATIONS:
 *    - Python: pathlib.Path with synchronous methods (read_text, write_text)
 *    - TypeScript: fs/promises with async/await (readFile, writeFile)
 *    - TypeScript requires async/await for all file I/O
 *
 * 2. TYPE DEFINITIONS:
 *    - Python: Runtime dict with string keys
 *    - TypeScript: Interface with compile-time type checking
 *    - TypeScript enforces task structure at compile time
 *
 * 3. CLASS PROPERTIES:
 *    - Python: Instance variables created in __init__
 *    - TypeScript: Property declarations with explicit types
 *    - TypeScript: private/public modifiers for access control
 *
 * 4. ERROR HANDLING:
 *    - Python: try/except with Exception types
 *    - TypeScript: try/catch with instanceof type guards
 *    - TypeScript: Type narrowing for error messages
 *
 * 5. JSON HANDLING:
 *    - Python: json.loads() / json.dumps()
 *    - TypeScript: JSON.parse() / JSON.stringify()
 *    - TypeScript: Type assertions needed for parsed JSON
 *
 * 6. GLOB OPERATIONS:
 *    - Python: path.glob("*.json") returns generator
 *    - TypeScript: await fs.readdir() with filtering
 *    - TypeScript: More explicit directory iteration
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import * as path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();
const TASKS_DIR = path.join(WORKDIR, ".tasks");

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use task tools to plan and track work.`;

const execAsync = promisify(exec);

/**
 * Task status enum
 * TypeScript: enum provides compile-time type safety and IntelliSense
 * Python: String literals with no compile-time checking
 */
enum TaskStatus {
    PENDING = "pending",
    IN_PROGRESS = "in_progress",
    COMPLETED = "completed",
}

/**
 * Task interface
 * TypeScript: Interface defines shape at compile time
 * Python: Would use TypedDict or runtime dict with no enforcement
 */
interface Task {
    id: number;
    subject: string;
    description: string;
    status: TaskStatus;
    blockedBy: number[];
    blocks: number[];
    owner: string;
}

/**
 * Task create input
 * TypeScript: Optional fields marked with ?
 */
interface TaskCreateInput {
    subject: string;
    description?: string;
}

/**
 * Task update input
 * TypeScript: All fields optional for partial updates
 */
interface TaskUpdateInput {
    status?: TaskStatus;
    addBlockedBy?: number[];
    addBlocks?: number[];
}

/**
 * TaskManager - CRUD with dependency graph, persisted as JSON files
 * TypeScript: Class with typed properties and async methods
 * Python: Class with instance variables and synchronous methods
 */
class TaskManager {
    private dir: string;
    private nextId: number;

    constructor(tasksDir: string) {
        this.dir = tasksDir;
        this.nextId = 0; // Will be initialized in async init
    }

    /**
     * Initialize the manager (must be called after constructor)
     * TypeScript: Async initialization pattern required for fs operations
     * Python: Can do all initialization in __init__ (synchronous)
     */
    async init(): Promise<void> {
        await fs.mkdir(this.dir, { recursive: true });
        this.nextId = (await this.maxId()) + 1;
    }

    /**
     * Get the highest task ID from existing files
     * TypeScript: Async function returning Promise<number>
     * Python: Synchronous method returning int
     */
    private async maxId(): Promise<number> {
        try {
            const files = await fs.readdir(this.dir);
            const taskFiles = files.filter(f => f.startsWith("task_") && f.endsWith(".json"));

            if (taskFiles.length === 0) {
                return 0;
            }

            const ids = taskFiles.map(f => {
                const match = f.match(/task_(\d+)\.json/);
                return match ? parseInt(match[1], 10) : 0;
            });

            return Math.max(...ids);
        } catch (error) {
            return 0;
        }
    }

    /**
     * Load a task from disk
     * TypeScript: Async method with typed return
     * Python: Synchronous method returning dict
     */
    private async load(taskId: number): Promise<Task> {
        const filePath = path.join(this.dir, `task_${taskId}.json`);

        try {
            const content = await fs.readFile(filePath, "utf-8");
            return JSON.parse(content) as Task;
        } catch (error) {
            if ((error as NodeJS.ErrnoException).code === "ENOENT") {
                throw new Error(`Task ${taskId} not found`);
            }
            throw error;
        }
    }

    /**
     * Save a task to disk
     * TypeScript: Async method with void return
     * Python: Synchronous method
     */
    private async save(task: Task): Promise<void> {
        const filePath = path.join(this.dir, `task_${task.id}.json`);
        await fs.writeFile(filePath, JSON.stringify(task, null, 2), "utf-8");
    }

    /**
     * Create a new task
     * TypeScript: Async method returning Promise<string>
     * Python: Synchronous method returning str
     */
    async create(subject: string, description: string = ""): Promise<string> {
        const task: Task = {
            id: this.nextId,
            subject,
            description,
            status: TaskStatus.PENDING,
            blockedBy: [],
            blocks: [],
            owner: "",
        };

        await this.save(task);
        this.nextId += 1;

        return JSON.stringify(task, null, 2);
    }

    /**
     * Get a task by ID
     * TypeScript: Async method with typed return
     * Python: Synchronous method
     */
    async get(taskId: number): Promise<string> {
        const task = await this.load(taskId);
        return JSON.stringify(task, null, 2);
    }

    /**
     * Update a task
     * TypeScript: Partial update pattern with optional parameters
     * Python: Multiple optional parameters with default None
     */
    async update(
        taskId: number,
        status?: TaskStatus,
        addBlockedBy?: number[],
        addBlocks?: number[]
    ): Promise<string> {
        const task = await this.load(taskId);

        if (status !== undefined) {
            if (!Object.values(TaskStatus).includes(status)) {
                throw new Error(`Invalid status: ${status}`);
            }
            task.status = status;

            // When a task is completed, remove it from all other tasks' blockedBy
            if (status === TaskStatus.COMPLETED) {
                await this.clearDependency(taskId);
            }
        }

        if (addBlockedBy !== undefined) {
            task.blockedBy = Array.from(new Set([...task.blockedBy, ...addBlockedBy]));
        }

        if (addBlocks !== undefined) {
            task.blocks = Array.from(new Set([...task.blocks, ...addBlocks]));

            // Bidirectional: also update the blocked tasks' blockedBy lists
            for (const blockedId of addBlocks) {
                try {
                    const blocked = await this.load(blockedId);
                    if (!blocked.blockedBy.includes(taskId)) {
                        blocked.blockedBy.push(taskId);
                        await this.save(blocked);
                    }
                } catch (error) {
                    // Task might not exist, ignore
                }
            }
        }

        await this.save(task);
        return JSON.stringify(task, null, 2);
    }

    /**
     * Remove a completed task from all other tasks' blockedBy lists
     * TypeScript: Async method iterating over directory
     * Python: Synchronous method with glob pattern
     */
    private async clearDependency(completedId: number): Promise<void> {
        try {
            const files = await fs.readdir(this.dir);
            const taskFiles = files.filter(f => f.startsWith("task_") && f.endsWith(".json"));

            for (const file of taskFiles) {
                const filePath = path.join(this.dir, file);
                const content = await fs.readFile(filePath, "utf-8");
                const task = JSON.parse(content) as Task;

                if (task.blockedBy.includes(completedId)) {
                    task.blockedBy = task.blockedBy.filter(id => id !== completedId);
                    await this.save(task);
                }
            }
        } catch (error) {
            // Directory might not exist yet
        }
    }

    /**
     * List all tasks with status indicators
     * TypeScript: Async method returning formatted string
     * Python: Synchronous method
     */
    async listAll(): Promise<string> {
        try {
            const files = await fs.readdir(this.dir);
            const taskFiles = files
                .filter(f => f.startsWith("task_") && f.endsWith(".json"))
                .sort();

            if (taskFiles.length === 0) {
                return "No tasks.";
            }

            const tasks: Task[] = [];
            for (const file of taskFiles) {
                const filePath = path.join(this.dir, file);
                const content = await fs.readFile(filePath, "utf-8");
                tasks.push(JSON.parse(content) as Task);
            }

            const lines: string[] = [];
            for (const task of tasks) {
                const markerMap = {
                    [TaskStatus.PENDING]: "[ ]",
                    [TaskStatus.IN_PROGRESS]: "[>]",
                    [TaskStatus.COMPLETED]: "[x]",
                };
                const marker = markerMap[task.status] || "[?]";
                const blocked = task.blockedBy.length > 0
                    ? ` (blocked by: ${task.blockedBy.join(", ")})`
                    : "";
                lines.push(`${marker} #${task.id}: ${task.subject}${blocked}`);
            }

            return lines.join("\n");
        } catch (error) {
            return "No tasks.";
        }
    }
}

