/**
 * Agent loop with notification draining
 * TypeScript: Async function with Message interface
 * Python: Synchronous function with list of dicts
 */
async function agentLoop(messages: any[]): Promise<void> {
    while (true) {
        // Drain background notifications and inject as system message before LLM call
        const notifs = BG.drainNotifications();
        if (notifs.length > 0 && messages.length > 0) {
            const notifText = notifs
                .map(n => `[bg:${n.task_id}] ${n.status}: ${n.result}`)
                .join("\n");

            messages.push({
                role: "user",
                content: `<background-results>\n${notifText}\n</background-results>`
            });
        }

        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: any[] = [];
        for (const block of response.content) {
            if (block.type === "tool_use") {
                const handler = TOOL_HANDLERS[block.name];
                try {
                    const output = handler
                        ? await handler(block.input)
                        : `Unknown tool: ${block.name}`;

                    console.log(`> ${block.name}:`);
                    console.log(String(output).substring(0, 200));

                    results.push({
                        type: "tool_result",
                        tool_use_id: block.id,
                        content: String(output),
                    });
                } catch (error) {
                    const errorMsg = error instanceof Error ? error.message : "Unknown error";
                    console.log(`> ${block.name}: Error: ${errorMsg}`);
                    results.push({
                        type: "tool_result",
                        tool_use_id: block.id,
                        content: `Error: ${errorMsg}`,
                    });
                }
            }
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 * TypeScript: Async function with readline interface
 * Python: while True with input()
 */
async function main(): Promise<void> {
    const history: any[] = [];
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> => {
        return new Promise((resolve) => {
            rl.question(prompt, resolve);
        });
    };

    console.log("\nSession 13: Background Tasks");
    console.log("Long-running commands execute in worker threads without blocking.\n");

    try {
        while (true) {
            const query = await question("\x1b[36ms13 >> \x1b[0m");

            if (query.trim().toLowerCase() === "q" || query.trim() === "exit" || query.trim() === "") {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if (block.type === "text") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        }
    } finally {
        // Clean up workers on exit
        BG.terminateAll();
        rl.close();
    }
}

// Run the main function
main().catch(console.error);

#!/usr/bin/env ts-node
// Harness: time -- the agent schedules its own future work.
// @ts-nocheck
// s14_cron_scheduler.ts - Cron / Scheduled Tasks
//
// The agent can schedule prompts for future execution using standard cron
// expressions. When a schedule matches the current time, it pushes a
// notification back into the main conversation loop.
//
//     Cron expression: 5 fields
//     +-------+-------+-------+-------+-------+
//     | min   | hour  | dom   | month | dow   |
//     | 0-59  | 0-23  | 1-31  | 1-12  | 0-6   |
//     +-------+-------+-------+-------+-------+
//     Examples:
//       "*/5 * * * *"   -> every 5 minutes
//       "0 9 * * 1"     -> Monday 9:00 AM
//       "30 14 * * *"   -> daily 2:30 PM
//
//     Two persistence modes:
//     +--------------------+-------------------------------+
//     | session-only       | In-memory list, lost on exit  |
//     | durable            | .claude/scheduled_tasks.json  |
//     +--------------------+-------------------------------+
//
//     Two trigger modes:
//     +--------------------+-------------------------------+
//     | recurring          | Repeats until deleted or      |
//     |                    |  7-day auto-expiry             |
//     | one-shot           | Fires once, then auto-deleted |
//     +--------------------+-------------------------------+
//
//     Jitter: recurring tasks can avoid exact minute boundaries.
//
//     Architecture:
//     +-------------------------------+
//     |  Background interval          |
//     |  (checks every 1 second)      |
//     |                               |
//     |  for each task:               |
//     |    if cronMatches(now):       |
//     |      enqueue notification     |
//     +-------------------------------+
//               |
//               v
//     [notification queue (array)]
//               |
//          (drained at top of agent_loop)
//               |
//               v
//     [injected as user messages before LLM call]
//
// Key idea: scheduling remembers future work, then hands it back to the
// same main loop when the time arrives.
//
// === TYPESCRIPT VS PYTHON ===
//
// 1. THREADING VS setInterval:
//    - Python: threading.Thread + threading.Event for background loop
//    - TypeScript: setInterval() with clearInterval() for cleanup
//    - Node.js is single-threaded; setInterval runs on the event loop
//
// 2. QUEUE:
//    - Python: queue.Queue with get_nowait() and Empty exception
//    - TypeScript: Simple array with push() and shift()
//    - No threading concerns in Node.js single-threaded model
//
// 3. FILE LOCKING:
//    - Python: PID-file with os.kill(pid, 0) for liveness check
//    - TypeScript: Same approach with process.kill(pid, 0)
//    - Both handle stale lock detection the same way
//
// 4. UUID:
//    - Python: uuid.uuid4().hex[:8]
//    - TypeScript: crypto.randomUUID().slice(0, 8)
//    - Both produce unique identifiers

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { promises as fs } from "fs";
import path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";
import crypto from "crypto";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();

const SCHEDULED_TASKS_FILE = path.join(WORKDIR, ".claude", "scheduled_tasks.json");
const CRON_LOCK_FILE = path.join(WORKDIR, ".claude", "cron.lock");
const AUTO_EXPIRY_DAYS = 7;
const JITTER_MINUTES = [0, 30]; // avoid these exact minutes for recurring tasks
const JITTER_OFFSET_MAX = 4;    // offset range in minutes

/**
 * CronLock - PID-file-based lock to prevent multiple sessions from
 * firing the same cron job.
 *
 * TypeScript: class with async file methods
 * Python: class CronLock with sync file methods
 */
class CronLock {
    private lockPath: string;

    constructor(lockPath?: string) {
        this.lockPath = lockPath || CRON_LOCK_FILE;
    }

    /**
     * Try to acquire the cron lock. Returns true on success.
     *
     * If a lock file exists, check whether the PID inside is still alive.
     * If the process is dead the lock is stale and we can take over.
     */
    async acquire(): Promise<boolean> {
        try {
            const content = await fs.readFile(this.lockPath, "utf-8");
            const storedPid = parseInt(content.trim(), 10);

            // PID liveness probe: send signal 0 (no-op) to check existence
            try {
                process.kill(storedPid, 0);
                // Process is alive -- lock is held by another session
                return false;
            } catch {
                // Stale lock (process dead or PID unparseable) -- fall through
            }
        } catch {
            // Lock file doesn't exist -- fall through
        }

        await fs.mkdir(path.dirname(this.lockPath), { recursive: true });
        await fs.writeFile(this.lockPath, String(process.pid), "utf-8");
        return true;
    }

    /**
     * Remove the lock file if it belongs to this process.
     */
    async release(): Promise<void> {
        try {
            const content = await fs.readFile(this.lockPath, "utf-8");
            const storedPid = parseInt(content.trim(), 10);
            if (storedPid === process.pid) {
                await fs.unlink(this.lockPath);
            }
        } catch {
            // File doesn't exist or can't be read
        }
    }
}

/**
 * Check if a 5-field cron expression matches a given datetime.
 *
 * Fields: minute hour day-of-month month day-of-week
 * Supports: star (any), star/N (every N), N (exact), N-M (range), N,M (list)
 *
 * TypeScript: function with Date object
 * Python: function with datetime object
 */
function cronMatches(expr: string, dt: Date): boolean {
    const fields = expr.trim().split(/\s+/);
    if (fields.length !== 5) return false;

    // JavaScript Date: getDay() returns 0=Sunday; cron uses 0=Sunday. Match!
    // Python weekday() returns 0=Monday; needs conversion.
    const values = [
        dt.getMinutes(),
        dt.getHours(),
        dt.getDate(),
        dt.getMonth() + 1,  // JS months are 0-indexed
        dt.getDay(),        // JS days are 0=Sunday, same as cron
    ];
    const ranges: [number, number][] = [[0, 59], [0, 23], [1, 31], [1, 12], [0, 6]];

    for (let i = 0; i < 5; i++) {
        if (!_fieldMatches(fields[i], values[i], ranges[i][0], ranges[i][1])) {
            return false;
        }
    }
    return true;
}

/**
 * Match a single cron field against a value.
 *
 * TypeScript: function with string/number params
 * Python: def _field_matches(field: str, value: int, lo: int, hi: int) -> bool
 */
function _fieldMatches(field: string, value: number, lo: number, hi: number): boolean {
    if (field === "*") return true;

    for (const part of field.split(",")) {
        let step = 1;
        let partToCheck = part;

        // Handle step: */N or N-M/S
        if (part.includes("/")) {
            const slashIdx = part.indexOf("/");
            partToCheck = part.slice(0, slashIdx);
            step = parseInt(part.slice(slashIdx + 1), 10);
        }

        if (partToCheck === "*") {
            // */N -- check if value is on the step grid
            if ((value - lo) % step === 0) return true;
        } else if (partToCheck.includes("-")) {
            // Range: N-M
            const dashIdx = partToCheck.indexOf("-");
            const start = parseInt(partToCheck.slice(0, dashIdx), 10);
            const end = parseInt(partToCheck.slice(dashIdx + 1), 10);
            if (start <= value && value <= end && (value - start) % step === 0) {
                return true;
            }
        } else {
            // Exact value
            if (parseInt(partToCheck, 10) === value) return true;
        }
    }

    return false;
}

/**
 * Scheduled task interface
 */
interface ScheduledTask {
    id: string;
    cron: string;
    prompt: string;
    recurring: boolean;
    durable: boolean;
    createdAt: number;
    jitter_offset?: number;
    last_fired?: number;
}

/**
 * CronScheduler - Manage scheduled tasks with background checking.
 *
 * Teaching version keeps only the core pieces: schedule records, a
 * minute checker, optional persistence, and a notification queue.
 *
 * TypeScript: class with setInterval-based background checking
 * Python: class with threading.Thread for background loop
 *
 * Key differences:
 * - TypeScript uses setInterval instead of threading
 * - Notification queue is a simple array (no threading concerns)
 * - File I/O is async throughout
 */
class CronScheduler {
    tasks: ScheduledTask[] = [];
    notifications: string[] = [];     // simple array + push/shift
    private _intervalId: ReturnType<typeof setInterval> | null = null;
    private _lastCheckMinute = -1;    // avoid double-firing within same minute

    /**
     * Load durable tasks and start the background check interval.
     * TypeScript: setInterval returns a handle for cleanup
     * Python: threading.Thread(daemon=True).start()
     */
    async start(): Promise<void> {
        await this._loadDurable();
        this._intervalId = setInterval(() => this._checkLoop(), 1000);
        const count = this.tasks.length;
        if (count) {
            console.log(`[Cron] Loaded ${count} scheduled tasks`);
        }
    }

    /**
     * Stop the background interval.
     * TypeScript: clearInterval with the interval handle
     * Python: self._stop_event.set(); self._thread.join()
     */
    stop(): void {
        if (this._intervalId !== null) {
            clearInterval(this._intervalId);
            this._intervalId = null;
        }
    }

    /**
     * Create a new scheduled task. Returns a status string.
     */
    create(
        cronExpr: string,
        prompt: string,
        recurring: boolean = true,
        durable: boolean = false
    ): string {
        const taskId = crypto.randomUUID().slice(0, 8);
        const now = Date.now() / 1000;

        const task: ScheduledTask = {
            id: taskId,
            cron: cronExpr,
            prompt,
            recurring,
            durable,
            createdAt: now,
        };

        // Jitter for recurring tasks: if the cron fires on :00 or :30,
        // note it so we can offset the check slightly
        if (recurring) {
            task.jitter_offset = this._computeJitter(cronExpr);
        }

        this.tasks.push(task);
        if (durable) {
            this._saveDurable();
        }

        const mode = recurring ? "recurring" : "one-shot";
        const store = durable ? "durable" : "session-only";
        return `Created task ${taskId} (${mode}, ${store}): cron=${cronExpr}`;
    }

    /**
     * Delete a scheduled task by ID.
     */
    delete(taskId: string): string {
        const before = this.tasks.length;
        this.tasks = this.tasks.filter((t) => t.id !== taskId);
        if (this.tasks.length < before) {
            this._saveDurable();
            return `Deleted task ${taskId}`;
        }
        return `Task ${taskId} not found`;
    }

    /**
     * List all scheduled tasks.
     */
    listTasks(): string {
        if (!this.tasks.length) return "No scheduled tasks.";
        const lines: string[] = [];
        for (const t of this.tasks) {
            const mode = t.recurring ? "recurring" : "one-shot";
            const store = t.durable ? "durable" : "session";
            const ageHours = (Date.now() / 1000 - t.createdAt) / 3600;
            lines.push(
                `  ${t.id}  ${t.cron}  [${mode}/${store}] ` +
                `(${ageHours.toFixed(1)}h old): ${t.prompt.slice(0, 60)}`
            );
        }
        return lines.join("\n");
    }

    /**
     * Drain all pending notifications from the queue.
     * TypeScript: Array with shift() (FIFO)
     * Python: queue.Queue with get_nowait() and Empty exception
     */
    drainNotifications(): string[] {
        const notifications: string[] = [];
        while (this.notifications.length > 0) {
            notifications.push(this.notifications.shift()!);
        }
        return notifications;
    }

    /**
     * If cron targets :00 or :30, return a small offset (1-4 minutes).
     */
    private _computeJitter(cronExpr: string): number {
        const fields = cronExpr.trim().split(/\s+/);
        if (fields.length < 1) return 0;
        const minuteField = fields[0];
        const minuteVal = parseInt(minuteField, 10);
        if (!isNaN(minuteVal) && JITTER_MINUTES.includes(minuteVal)) {
            // Deterministic jitter based on the expression hash
            const hash = cronExpr.split("").reduce((acc, char) => {
                return ((acc << 5) - acc + char.charCodeAt(0)) | 0;
            }, 0);
            return (Math.abs(hash) % JITTER_OFFSET_MAX) + 1;
        }
        return 0;
    }

    /**
     * Background check: check every second if any task is due.
     * TypeScript: called by setInterval, runs on the event loop
     * Python: runs in a background thread
     */
    private _checkLoop(): void {
        const now = new Date();
        const currentMinute = now.getHours() * 60 + now.getMinutes();

        // Only check once per minute to avoid double-firing
        if (currentMinute !== this._lastCheckMinute) {
            this._lastCheckMinute = currentMinute;
            this._checkTasks(now);
        }
    }

    /**
     * Check all tasks against current time, fire matches.
     */
    private _checkTasks(now: Date): void {
        const expired: string[] = [];
        const firedOneshots: string[] = [];

        for (const task of this.tasks) {
            // Auto-expiry: recurring tasks older than 7 days
            const ageDays = (Date.now() / 1000 - task.createdAt) / 86400;
            if (task.recurring && ageDays > AUTO_EXPIRY_DAYS) {
                expired.push(task.id);
                continue;
            }

            // Apply jitter offset for the match check
            let checkTime = now;
            const jitter = task.jitter_offset || 0;
            if (jitter) {
                checkTime = new Date(now.getTime() - jitter * 60000);
            }

            if (cronMatches(task.cron, checkTime)) {
                const notification =
                    `[Scheduled task ${task.id}]: ${task.prompt}`;
                this.notifications.push(notification);
                task.last_fired = Date.now() / 1000;
                console.log(`[Cron] Fired: ${task.id}`);

                if (!task.recurring) {
                    firedOneshots.push(task.id);
                }
            }
        }

        // Clean up expired and one-shot tasks
        if (expired.length || firedOneshots.length) {
            const removeIds = new Set([...expired, ...firedOneshots]);
            this.tasks = this.tasks.filter((t) => !removeIds.has(t.id));
            for (const tid of expired) {
                console.log(`[Cron] Auto-expired: ${tid} (older than ${AUTO_EXPIRY_DAYS} days)`);
            }
            for (const tid of firedOneshots) {
                console.log(`[Cron] One-shot completed and removed: ${tid}`);
            }
            this._saveDurable();
        }
    }

    /**
     * Load durable tasks from .claude/scheduled_tasks.json.
     */
    private async _loadDurable(): Promise<void> {
        try {
            const data = JSON.parse(await fs.readFile(SCHEDULED_TASKS_FILE, "utf-8"));
            // Only load durable tasks
            this.tasks = data.filter((t: any) => t.durable);
        } catch {
            // File doesn't exist or can't be parsed
        }
    }

    /**
     * Save durable tasks to disk.
     */
    private _saveDurable(): void {
        const durable = this.tasks.filter((t) => t.durable);
        const dir = path.dirname(SCHEDULED_TASKS_FILE);
        fs.mkdir(dir, { recursive: true })
            .then(() => fs.writeFile(
                SCHEDULED_TASKS_FILE,
                JSON.stringify(durable, null, 2) + "\n",
                "utf-8"
            ))
            .catch((error) => {
                console.error(`[Cron] Error saving tasks: ${error}`);
            });
    }

    /**
     * On startup, check each durable task's last_fired time.
     *
     * If a task should have fired while the session was closed (i.e.
     * the gap between last_fired and now contains at least one cron match),
     * flag it as missed. The caller can then let the user decide whether
     * to run or discard each missed task.
     */
    detectMissedTasks(): { id: string; cron: string; prompt: string; missed_at: string }[] {
        const now = new Date();
        const missed: { id: string; cron: string; prompt: string; missed_at: string }[] = [];

        for (const task of this.tasks) {
            if (task.last_fired === undefined || task.last_fired === null) continue;

            const lastDt = new Date(task.last_fired * 1000);
            // Walk forward minute-by-minute from last_fired to now (cap at 24h)
            const check = new Date(lastDt.getTime() + 60000);
            const cap = new Date(Math.min(now.getTime(), lastDt.getTime() + 24 * 3600000));

            while (check <= cap) {
                if (cronMatches(task.cron, check)) {
                    missed.push({
                        id: task.id,
                        cron: task.cron,
                        prompt: task.prompt,
                        missed_at: check.toISOString(),
                    });
                    break; // one miss is enough to flag it
                }
                check.setTime(check.getTime() + 60000);
            }
        }
        return missed;
    }
}

// Global scheduler
const scheduler = new CronScheduler();

/**
 * Safe path validation
 */
function safePath(filePath: string): string {
    const resolved = path.resolve(WORKDIR, filePath);
    const relative = path.relative(WORKDIR, resolved);

    if (relative.startsWith("..")) {
        throw new Error(`Path escapes workspace: ${filePath}`);
    }

    return resolved;
}

const execAsync = promisify(exec);

async function runBash(command: string): Promise<string> {
    const DANGEROUS = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"] as const;

    if (DANGEROUS.some((d) => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });

        const output = (stdout + stderr).trim();
        return output ? output.slice(0, 50000) : "(no output)";
    } catch (error) {
        if (error instanceof Error && "killed" in error) {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const text = await fs.readFile(safeFilePath, "utf-8");
        const lines = text.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = lines.slice(0, limit);
            truncated.push(`... (${lines.length - limit} more lines)`);
            return truncated.join("\n");
        }

        return text.slice(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const directory = path.dirname(safeFilePath);
        await fs.mkdir(directory, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes to ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

async function runEdit(
    filePath: string,
    oldText: string,
    newText: string
): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const newContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, newContent, "utf-8");

        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Types for message handling
 */
interface Message {
    role: "user" | "assistant";
    content: string | ContentBlock[];
}

interface ContentBlock {
    type: string;
    id?: string;
    name?: string;
    input?: Record<string, unknown>;
    text?: string;
    tool_use_id?: string;
    content?: string;
}

interface ToolResultBlock {
    type: "tool_result";
    tool_use_id: string;
    content: string;
}

/**
 * Tool handler type
 */
type ToolHandler = (input: Record<string, unknown>) => Promise<string>;

/**
 * THE DISPATCH MAP: Includes cron tools
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => {
        const command = input.command as string;
        return runBash(command);
    },

    read_file: async (input) => {
        const filePath = input.path as string;
        const limit = input.limit as number | undefined;
        return runRead(filePath, limit);
    },

    write_file: async (input) => {
        const filePath = input.path as string;
        const content = input.content as string;
        return runWrite(filePath, content);
    },

    edit_file: async (input) => {
        const filePath = input.path as string;
        const oldText = input.old_text as string;
        const newText = input.new_text as string;
        return runEdit(filePath, oldText, newText);
    },

    cron_create: async (input) => {
        const cronExpr = input.cron as string;
        const prompt = input.prompt as string;
        const recurring = (input.recurring ?? true) as boolean;
        const durable = (input.durable ?? false) as boolean;
        return scheduler.create(cronExpr, prompt, recurring, durable);
    },

    cron_delete: async (input) => {
        const id = input.id as string;
        return scheduler.delete(id);
    },

    cron_list: async () => {
        return scheduler.listTasks();
    },
};

/**
 * Tool definitions for Anthropic API -- includes cron tools
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" },
            },
            required: ["command"] as const,
        },
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" },
            },
            required: ["path"] as const,
        },
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" },
            },
            required: ["path", "content"] as const,
        },
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" },
            },
            required: ["path", "old_text", "new_text"] as const,
        },
    },
    {
        name: "cron_create",
        description: "Schedule a recurring or one-shot task with a cron expression.",
        input_schema: {
            type: "object" as const,
            properties: {
                cron: {
                    type: "string",
                    description: "5-field cron expression: 'min hour dom month dow'",
                },
                prompt: {
                    type: "string",
                    description: "The prompt to inject when the task fires",
                },
                recurring: {
                    type: "boolean",
                    description: "true=repeat, false=fire once then delete. Default true.",
                },
                durable: {
                    type: "boolean",
                    description: "true=persist to disk, false=session-only. Default false.",
                },
            },
            required: ["cron", "prompt"] as const,
        },
    },
    {
        name: "cron_delete",
        description: "Delete a scheduled task by ID.",
        input_schema: {
            type: "object" as const,
            properties: {
                id: {
                    type: "string",
                    description: "Task ID to delete",
                },
            },
            required: ["id"] as const,
        },
    },
    {
        name: "cron_list",
        description: "List all scheduled tasks.",
        input_schema: {
            type: "object" as const,
            properties: {},
        },
    },
];

const SYSTEM = `You are a coding agent at ${WORKDIR}. Use tools to solve tasks.\n\nYou can schedule future work with cron_create. Tasks fire automatically and their prompts are injected into the conversation.`;

/**
 * Cron-aware agent loop.
 *
 * Before each LLM call, drain the notification queue and inject any
 * fired task prompts as user messages. This is how the agent "wakes up"
 * to handle scheduled work.
 *
 * TypeScript: async function with array-based notification draining
 * Python: def agent_loop(messages: list)
 */
async function agentLoop(messages: Message[]): Promise<void> {
    while (true) {
        // Drain scheduled task notifications
        const notifications = scheduler.drainNotifications();
        for (const note of notifications) {
            console.log(`[Cron notification] ${note.slice(0, 100)}`);
            messages.push({ role: "user", content: note });
        }

        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: ToolResultBlock[] = [];

        for (const block of response.content) {
            if (block.type === "tool_use" && block.id && block.name && block.input) {
                console.log(`> ${block.name}:`);

                const handler = TOOL_HANDLERS[block.name];
                let output: string;

                if (handler) {
                    try {
                        output = await handler(block.input);
                    } catch (error) {
                        output = `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
                    }
                } else {
                    output = `Unknown tool: ${block.name}`;
                }

                console.log(output.slice(0, 200));

                results.push({
                    type: "tool_result",
                    tool_use_id: block.id,
                    content: output,
                });
            }
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    await scheduler.start();
    console.log("[Cron scheduler running. Background checks every second.]");
    console.log("[Commands: /cron to list tasks, /test to fire a test notification]");

    const history: Message[] = [];

    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> =>
        new Promise((resolve) => {
            rl.question(prompt, resolve);
        });

    console.log("Session 14: Cron Scheduler. Type 'q' to exit.\n");

    while (true) {
        try {
            const query = await question("\x1b[36ms14 >> \x1b[0m");

            if (
                query.trim().toLowerCase() === "q" ||
                query.trim().toLowerCase() === "exit" ||
                query.trim() === ""
            ) {
                scheduler.stop();
                break;
            }

            if (query.trim() === "/cron") {
                console.log(scheduler.listTasks());
                continue;
            }

            if (query.trim() === "/test") {
                // Manually enqueue a test notification for demonstration
                scheduler.notifications.push("[Scheduled task test-0000]: This is a test notification.");
                console.log("[Test notification enqueued. It will be injected on your next message.]");
                continue;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if ("text" in block && typeof block.text === "string") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        } catch (error) {
            if (
                error instanceof Error &&
                (error.message.includes("EOF") || error.message.includes("SIGINT"))
            ) {
                scheduler.stop();
                break;
            }
            console.error("Error:", error);
        }
    }

    rl.close();
}

main().catch((error) => {
    console.error("Fatal error:", error);
    scheduler.stop();
    process.exit(1);
});

#!/usr/bin/env ts-node
// Harness: multi-agent orchestration -- teammates with async mailboxes.
/**
 * s15_agent_teams.ts - Agent Teams
 *
 * Persistent named agents with file-based JSONL inboxes. Each teammate runs
 * its own agent loop in a separate worker thread. Communication via append-only inboxes.
 *
 *     Subagent (s04):  spawn -> execute -> return summary -> destroyed
 *     Teammate (s15):  spawn -> work -> idle -> work -> ... -> shutdown
 *
 *     .team/config.json                   .team/inbox/
 *     +----------------------------+      +------------------+
 *     | {"team_name": "default",   |      | alice.jsonl      |
 *     |  "members": [              |      | bob.jsonl        |
 *     |    {"name":"alice",        |      | lead.jsonl       |
 *     |     "role":"coder",        |      +------------------+
 *     |     "status":"idle"}       |
 *     |  ]}                        |      send_message("alice", "fix bug"):
 *     +----------------------------+        open("alice.jsonl", "a").write(msg)
 *
 *                                         read_inbox("alice"):
 *     spawn_teammate("alice","coder",...)   msgs = [json.loads(l) for l in ...]
 *          |                                open("alice.jsonl", "w").close()
 *          v                                return msgs  # drain
 *     Worker: alice          Worker: bob
 *     +------------------+      +------------------+
 *     | agent_loop       |      | agent_loop       |
 *     | status: working  |      | status: idle     |
 *     | ... runs tools   |      | ... waits ...    |
 *     | status -> idle   |      |                  |
 *     +------------------+      +------------------+
 *
 *     5 message types (all declared, not all handled here):
 *     +-------------------------+-----------------------------------+
 *     | message                 | Normal text message               |
 *     | broadcast               | Sent to all teammates             |
 *     | shutdown_request        | Request graceful shutdown (s10)   |
 *     | shutdown_response       | Approve/reject shutdown (s10)     |
 *     | plan_approval_response  | Approve/reject plan (s10)         |
 *     +-------------------------+-----------------------------------+
 *
 * Key insight: "Teammates that can talk to each other."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. THREADING MODEL:
 *    - Python: threading.Thread with shared memory
 *    - TypeScript: Worker Threads with message passing
 *    - TypeScript: No shared memory, communicate via messages
 *
 * 2. CONFIG PERSISTENCE:
 *    - Python: Dict loaded from JSON file
 *    - TypeScript: Interface with type safety
 *    - Both: Save to config.json after changes
 *
 * 3. INBOX MANAGEMENT:
 *    - Python: Direct file I/O with Path objects
 *    - TypeScript: fs.promises with async/await
 *    - Both: JSONL format (one JSON per line)
 *
 * 4. TEAMMATE STATUS:
 *    - Python: String status in config dict
 *    - TypeScript: Enum for compile-time safety
 *    - Both: Track status (idle, working, shutdown)
 *
 * 5. WORKER LIFECYCLE:
 *    - Python: Daemon threads auto-exit
 *    - TypeScript: Workers must be explicitly terminated
 *    - TypeScript: Terminate all workers on shutdown
 *
 * 6. MESSAGE PASSING:
 *    - Python: Shared memory with threading.Lock()
 *    - TypeScript: postMessage/on('message') events
 *    - TypeScript: Structured clone for data transfer
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { existsSync, promises as fs } from "fs";
import * as path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";
import { Worker } from "worker_threads";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();
const TEAM_DIR = path.join(WORKDIR, ".team");
const INBOX_DIR = path.join(TEAM_DIR, "inbox");

const SYSTEM = `You are a team lead at ${WORKDIR}. Spawn teammates and communicate via inboxes.`;

const execAsync = promisify(exec);

/**
 * Valid message types
 * TypeScript: Readonly array for compile-time safety
 * Python: Set of strings
 */
const VALID_MSG_TYPES = [
    "message",
    "broadcast",
    "shutdown_request",
    "shutdown_response",
    "plan_approval_response",
] as const;

type MessageType = typeof VALID_MSG_TYPES[number];

/**
 * Teammate status enum
 * TypeScript: enum for compile-time type safety
 * Python: String literals
 */
enum TeammateStatus {
    IDLE = "idle",
    WORKING = "working",
    SHUTDOWN = "shutdown",
}

/**
 * Teammate member interface
 * TypeScript: Interface with required and optional fields
 * Python: Dict with keys
 */
interface TeammateMember {
    name: string;
    role: string;
    status: TeammateStatus;
}

/**
 * Team config interface
 * TypeScript: Interface for type safety
 * Python: Dict with keys
 */
interface TeamConfig {
    team_name: string;
    members: TeammateMember[];
}

/**
 * Message interface
 * TypeScript: Interface defining message structure
 */
interface TeamMessage {
    type: MessageType;
    from: string;
    content: string;
    timestamp: number;
    [key: string]: any;
}

/**
 * MessageBus: JSONL inbox per teammate
 * TypeScript: Class with async file operations
 * Python: Class with synchronous file operations
 */
class MessageBus {
    private dir: string;

    constructor(inboxDir: string) {
        this.dir = inboxDir;
    }

    /**
     * Initialize inbox directory
     * TypeScript: Async method
     * Python: Synchronous mkdir in __init__
     */
    async init(): Promise<void> {
        await fs.mkdir(this.dir, { recursive: true });
    }

    /**
     * Send message to teammate
     * TypeScript: Async method with type validation
     * Python: Synchronous method
     */
    async send(
        sender: string,
        to: string,
        content: string,
        msgType: MessageType = "message",
        extra: Record<string, any> = {}
    ): Promise<string> {
        if (!VALID_MSG_TYPES.includes(msgType)) {
            return `Error: Invalid type '${msgType}'. Valid: ${VALID_MSG_TYPES.join(", ")}`;
        }

        const msg: TeamMessage = {
            type: msgType,
            from: sender,
            content,
            timestamp: Date.now() / 1000,
            ...extra
        };

        const inboxPath = path.join(this.dir, `${to}.jsonl`);
        const jsonLine = JSON.stringify(msg) + "\n";

        await fs.appendFile(inboxPath, jsonLine, "utf-8");
        return `Sent ${msgType} to ${to}`;
    }

    /**
     * Read and drain inbox
     * TypeScript: Async method returning Promise
     * Python: Synchronous method returning list
     */
    async readInbox(name: string): Promise<TeamMessage[]> {
        const inboxPath = path.join(this.dir, `${name}.jsonl`);

        try {
            const content = await fs.readFile(inboxPath, "utf-8");
            const lines = content.trim().split("\n");
            const messages: TeamMessage[] = [];

            for (const line of lines) {
                if (line) {
                    messages.push(JSON.parse(line));
                }
            }

            // Clear inbox after reading
            await fs.writeFile(inboxPath, "", "utf-8");

            return messages;
        } catch (error) {
            return [];
        }
    }

    /**
     * Broadcast message to all teammates except sender
     * TypeScript: Async method with array iteration
     * Python: Synchronous method
     */
    async broadcast(sender: string, content: string, teammates: string[]): Promise<string> {
        let count = 0;
        for (const name of teammates) {
            if (name !== sender) {
                await this.send(sender, name, content, "broadcast");
                count++;
            }
        }
        return `Broadcast to ${count} teammates`;
    }
}

// Initialize message bus
const BUS = new MessageBus(INBOX_DIR);

/**
 * TeammateManager: persistent named agents with config.json
 * TypeScript: Class with Worker management
 * Python: Class with threading.Thread management
 */
class TeammateManager {
    private dir: string;
    private configPath: string;
    private config: TeamConfig;
    private workers: Map<string, Worker> = new Map();

    constructor(teamDir: string) {
        this.dir = teamDir;
        this.configPath = path.join(teamDir, "config.json");
        this.config = { team_name: "default", members: [] };
    }

    /**
     * Initialize manager
     * TypeScript: Async initialization pattern
     * Python: Can do all initialization in __init__
     */
    async init(): Promise<void> {
        await fs.mkdir(this.dir, { recursive: true });
        await this.loadConfig();
        await BUS.init();
    }

    /**
     * Load config from file
     * TypeScript: Async method
     * Python: Synchronous method
     */
    private async loadConfig(): Promise<void> {
        try {
            const content = await fs.readFile(this.configPath, "utf-8");
            this.config = JSON.parse(content);
        } catch (error) {
            // Use default config if file doesn't exist
            this.config = { team_name: "default", members: [] };
        }
    }

    /**
     * Save config to file
     * TypeScript: Async method
     * Python: Synchronous method
     */
    private async saveConfig(): Promise<void> {
        await fs.writeFile(
            this.configPath,
            JSON.stringify(this.config, null, 2),
            "utf-8"
        );
    }

    /**
     * Find member by name
     * TypeScript: Method returning member or undefined
     * Python: Method returning member or None
     */
    private findMember(name: string): TeammateMember | undefined {
        return this.config.members.find(m => m.name === name);
    }

    /**
     * Spawn a new teammate
     * TypeScript: Creates Worker, returns immediately
     * Python: Creates Thread, returns immediately
     */
    async spawn(name: string, role: string, prompt: string): Promise<string> {
        const member = this.findMember(name);

        if (member) {
            if (member.status !== TeammateStatus.IDLE && member.status !== TeammateStatus.SHUTDOWN) {
                return `Error: '${name}' is currently ${member.status}`;
            }
            member.status = TeammateStatus.WORKING;
            member.role = role;
        } else {
            const newMember: TeammateMember = {
                name,
                role,
                status: TeammateStatus.WORKING
            };
            this.config.members.push(newMember);
        }

        await this.saveConfig();

        // Create worker for teammate
        const jsWorkerPath = path.join(__dirname, "teammate-worker.js");
        const tsWorkerPath = path.join(__dirname, "teammate-worker.ts");
        const workerPath = existsSync(jsWorkerPath) ? jsWorkerPath : tsWorkerPath;
        const worker = new Worker(workerPath, {
            workerData: {
                teammateName: name,
                role,
                prompt,
                workdir: WORKDIR,
                inboxDir: INBOX_DIR,
                modelId: MODEL,
                apiBase: process.env.ANTHROPIC_BASE_URL,
                sessionMode: "s15",
                protocolMode: "base",
            },
            ...(workerPath.endsWith(".ts")
                ? { execArgv: ["--loader", "ts-node/esm"] }
                : {}),
        });

        // Handle worker completion
        worker.on("message", (msg: any) => {
            if (msg.type === "teammate_complete") {
                const m = this.findMember(name);
                if (m) {
                    m.status = msg.final_status === "shutdown"
                        ? TeammateStatus.SHUTDOWN
                        : TeammateStatus.IDLE;
                    this.saveConfig();
                }
                this.workers.delete(name);
            } else if (msg.type === "tool_use") {
                console.log(`  [${msg.teammate}] ${msg.tool}: ${msg.output}`);
            }
        });

        worker.on("error", (error) => {
            console.error(`  [${name}] Worker error: ${error.message}`);
            const m = this.findMember(name);
            if (m) {
                m.status = TeammateStatus.IDLE;
                this.saveConfig();
            }
            this.workers.delete(name);
        });

        worker.on("exit", (code) => {
            if (code !== 0) {
                const m = this.findMember(name);
                if (m && m.status === TeammateStatus.WORKING) {
                    m.status = TeammateStatus.IDLE;
                    this.saveConfig();
                }
            }
            this.workers.delete(name);
        });

        this.workers.set(name, worker);

        return `Spawned '${name}' (role: ${role})`;
    }

    /**
     * List all teammates
     * TypeScript: Async method
     * Python: Synchronous method
     */
    async listAll(): Promise<string> {
        if (this.config.members.length === 0) {
            return "No teammates.";
        }

        const lines: string[] = [`Team: ${this.config.team_name}`];
        for (const m of this.config.members) {
            lines.push(`  ${m.name} (${m.role}): ${m.status}`);
        }
        return lines.join("\n");
    }

    /**
     * Get all member names
     * TypeScript: Method returning string array
     * Python: Method returning list
     */
    memberNames(): string[] {
        return this.config.members.map(m => m.name);
    }

    /**
     * Terminate all workers
     * TypeScript: Explicit cleanup required
     * Python: Daemon threads auto-clean
     */
    terminateAll(): void {
        for (const [name, worker] of Array.from(this.workers.entries())) {
            worker.terminate();
            this.workers.delete(name);
        }
    }
}

// Initialize teammate manager
const TEAMMATES = new TeammateManager(TEAM_DIR);

// -- Base tool implementations --
/**
 * Safe path resolution
 */
function safePath(p: string): string {
    const resolvedPath = path.resolve(WORKDIR, p);
    if (!resolvedPath.startsWith(WORKDIR)) {
        throw new Error(`Path escapes workspace: ${p}`);
    }
    return resolvedPath;
}

/**
 * Run bash command
 */
async function runBash(command: string): Promise<string> {
    const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
    if (dangerous.some(d => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });
        const output = (stdout + stderr).trim();
        return output ? output.substring(0, 50000) : "(no output)";
    } catch (error) {
        if ((error as any).code === "ETIMEDOUT") {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Read file contents
 */
async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");
        const lines = content.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = [
                ...lines.slice(0, limit),
                `... (${lines.length - limit} more)`
            ];
            return truncated.join("\n").substring(0, 50000);
        }

        return content.substring(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Write content to file
 */
async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const dir = path.dirname(safeFilePath);
        await fs.mkdir(dir, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Edit file by replacing exact text
 */
async function runEdit(filePath: string, oldText: string, newText: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const updatedContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, updatedContent, "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

// Type for tool handler functions
type ToolHandler = (input: any) => Promise<string> | string;

/**
 * Tool handlers map
 */
const TOOL_HANDLERS: Record<string, ToolHandler> = {
    bash: async (input) => await runBash(input.command),
    read_file: async (input) => await runRead(input.path, input.limit),
    write_file: async (input) => await runWrite(input.path, input.content),
    edit_file: async (input) => await runEdit(input.path, input.old_text, input.new_text),
    spawn_teammate: async (input) => await TEAMMATES.spawn(input.name, input.role, input.prompt),
    list_teammates: async () => await TEAMMATES.listAll(),
    send_message: async (input) => await BUS.send(
        "lead",
        input.to,
        input.content,
        input.msg_type || "message"
    ),
    read_inbox: async () => JSON.stringify(await BUS.readInbox("lead"), null, 2),
    broadcast: async (input) => await BUS.broadcast(
        "lead",
        input.content,
        TEAMMATES.memberNames()
    ),
};

/**
 * Tool definitions for the API
 */
const TOOLS = [
    {
        name: "bash",
        description: "Run a shell command.",
        input_schema: {
            type: "object" as const,
            properties: {
                command: { type: "string" }
            },
            required: ["command"] as const
        }
    },
    {
        name: "read_file",
        description: "Read file contents.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                limit: { type: "integer" }
            },
            required: ["path"] as const
        }
    },
    {
        name: "write_file",
        description: "Write content to file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                content: { type: "string" }
            },
            required: ["path", "content"] as const
        }
    },
    {
        name: "edit_file",
        description: "Replace exact text in file.",
        input_schema: {
            type: "object" as const,
            properties: {
                path: { type: "string" },
                old_text: { type: "string" },
                new_text: { type: "string" }
            },
            required: ["path", "old_text", "new_text"] as const
        }
    },
    {
        name: "spawn_teammate",
        description: "Spawn a new teammate agent.",
        input_schema: {
            type: "object" as const,
            properties: {
                name: { type: "string" },
                role: { type: "string" },
                prompt: { type: "string" }
            },
            required: ["name", "role", "prompt"] as const
        }
    },
    {
        name: "list_teammates",
        description: "List all teammates and their status.",
        input_schema: {
            type: "object" as const,
            properties: {}
        }
    },
    {
        name: "send_message",
        description: "Send a message to a teammate.",
        input_schema: {
            type: "object" as const,
            properties: {
                to: { type: "string" },
                content: { type: "string" },
                msg_type: {
                    type: "string",
                    enum: VALID_MSG_TYPES
                }
            },
            required: ["to", "content"] as const
        }
    },
    {
        name: "read_inbox",
        description: "Read and drain the lead's inbox.",
        input_schema: {
            type: "object" as const,
            properties: {}
        }
    },
    {
        name: "broadcast",
        description: "Send a message to all teammates.",
        input_schema: {
            type: "object" as const,
            properties: {
                content: { type: "string" }
            },
            required: ["content"] as const
        }
    },
];

/**
 * Agent loop
 */
async function agentLoop(messages: any[]): Promise<void> {
    while (true) {
        const inbox = await BUS.readInbox("lead");
        if (inbox.length > 0) {
            messages.push({
                role: "user",
                content: `<inbox>${JSON.stringify(inbox, null, 2)}</inbox>`,
            });
        }

        const response = await client.messages.create({
            model: MODEL,
            system: SYSTEM,
            messages: messages,
            tools: TOOLS,
            max_tokens: 8000,
        });

        messages.push({
            role: "assistant",
            content: response.content,
        });

        if (response.stop_reason !== "tool_use") {
            return;
        }

        const results: any[] = [];
        for (const block of response.content) {
            if (block.type === "tool_use") {
                const handler = TOOL_HANDLERS[block.name];
                try {
                    const output = handler
                        ? await handler(block.input)
                        : `Unknown tool: ${block.name}`;

                    console.log(`> ${block.name}:`);
                    console.log(String(output).substring(0, 200));

                    results.push({
                        type: "tool_result",
                        tool_use_id: block.id,
                        content: String(output),
                    });
                } catch (error) {
                    const errorMsg = error instanceof Error ? error.message : "Unknown error";
                    console.log(`> ${block.name}: Error: ${errorMsg}`);
                    results.push({
                        type: "tool_result",
                        tool_use_id: block.id,
                        content: `Error: ${errorMsg}`,
                    });
                }
            }
        }

        messages.push({
            role: "user",
            content: results,
        });
    }
}

/**
 * Main REPL loop
 */
async function main(): Promise<void> {
    await TEAMMATES.init();

    const history: any[] = [];
    const rl = readline.createInterface({
        input: process.stdin,
        output: process.stdout,
    });

    const question = (prompt: string): Promise<string> => {
        return new Promise((resolve) => {
            rl.question(prompt, resolve);
        });
    };

    console.log("\nSession 15: Agent Teams");
    console.log("Spawn persistent teammates that communicate via JSONL inboxes.\n");

    try {
        while (true) {
            const query = await question("\x1b[36ms15 >> \x1b[0m");

            if (query.trim().toLowerCase() === "q" || query.trim() === "exit" || query.trim() === "") {
                break;
            }

            history.push({
                role: "user",
                content: query,
            });

            await agentLoop(history);

            const responseContent = history[history.length - 1].content;
            if (Array.isArray(responseContent)) {
                for (const block of responseContent) {
                    if (block.type === "text") {
                        console.log(block.text);
                    }
                }
            }
            console.log();
        }
    } finally {
        TEAMMATES.terminateAll();
        rl.close();
    }
}

// Run the main function
main().catch(console.error);

#!/usr/bin/env ts-node
// Harness: coordination patterns -- request-response protocols for agent negotiation.
// @ts-nocheck
/**
 * s16_team_protocols.ts - Team Protocols
 *
 * Shutdown protocol and plan approval protocol, both using the same
 * request_id correlation pattern. Builds on s15's team messaging.
 *
 *     Shutdown FSM: pending -> approved | rejected
 *
 *     Lead                              Teammate
 *     +---------------------+          +---------------------+
 *     | shutdown_request     |          |                     |
 *     | {                    | -------> | receives request    |
 *     |   request_id: abc    |          | decides: approve?   |
 *     | }                    |          |                     |
 *     +---------------------+          +---------------------+
 *                                          |
 *     +---------------------+          +-------v-------------+
 *     | shutdown_response    | <------- | shutdown_response   |
 *     | {                    |          | {                   |
 *     |   request_id: abc    |          |   request_id: abc   |
 *     |   approve: true      |          |   approve: true     |
 *     | }                    |          | }                   |
 *     +---------------------+          +---------------------+
 *             |
 *             v
 *     status -> "shutdown", thread stops
 *
 *     Plan approval FSM: pending -> approved | rejected
 *
 *     Teammate                          Lead
 *     +---------------------+          +---------------------+
 *     | plan_approval        |          |                     |
 *     | submit: {plan:"..."}| -------> | reviews plan text   |
 *     +---------------------+          | approve/reject?     |
 *                                      +---------------------+
 *                                              |
 *     +---------------------+          +-------v-------------+
 *     | plan_approval_resp   | <------- | plan_approval       |
 *     | {approve: true}      |          | review: {req_id,    |
 *     +---------------------+          |   approve: true}     |
 *                                      +---------------------+
 *
 *     Trackers: {request_id: {"target|from": name, "status": "pending|..."}}
 *
 * Key insight: "Same request_id correlation pattern, two domains."
 *
 * === TYPESCRIPT VS PYTHON ===
 *
 * 1. REQUEST TRACKING:
 *    - Python: Dict with threading.Lock() for thread safety
 *    - TypeScript: Map<string, ProtocolRequest> (no locks needed - single-threaded event loop)
 *    - TypeScript: Async operations don't block the event loop
 *
 * 2. UUID GENERATION:
 *    - Python: uuid.uuid4() returns UUID object
 *    - TypeScript: crypto.randomUUID() returns string
 *    - TypeScript: Slice with .substring() instead of [:8]
 *
 * 3. PROTOCOL INTERFACES:
 *    - Python: Dict with string keys
 *    - TypeScript: Interface with type safety
 *    - TypeScript: Union types for request/response variants
 *
 * 4. STATE MANAGEMENT:
 *    - Python: String literals for status
 *    - TypeScript: Enum for compile-time safety
 *    - TypeScript: RequestStatus enum (pending, approved, rejected)
 *
 * 5. PROTOCOL HANDLERS:
 *    - Python: Functions with global state and locks
 *    - TypeScript: ProtocolManager class with encapsulated state
 *    - TypeScript: Async methods for all protocol operations
 *
 * 6. MESSAGE PASSING:
 *    - Python: Global MessageBus instance
 *    - TypeScript: Shared MessageBus instance (same pattern)
 *    - TypeScript: Type-safe message interfaces
 */

import Anthropic from "@anthropic-ai/sdk";
import { config } from "dotenv";
import { existsSync, promises as fs } from "fs";
import * as path from "path";
import { exec } from "child_process";
import { promisify } from "util";
import * as readline from "readline";
import { Worker } from "worker_threads";
import { randomUUID } from "crypto";

// Load environment variables
config();

if (process.env.ANTHROPIC_BASE_URL) {
    delete process.env.ANTHROPIC_AUTH_TOKEN;
}

const WORKDIR = process.cwd();
const client = new Anthropic({
    baseURL: process.env.ANTHROPIC_BASE_URL,
});
const MODEL = process.env.MODEL_ID ?? (() => {
    throw new Error("MODEL_ID environment variable is required.");
})();
const TEAM_DIR = path.join(WORKDIR, ".team");
const INBOX_DIR = path.join(TEAM_DIR, "inbox");

const SYSTEM = `You are a team lead at ${WORKDIR}. Manage teammates with shutdown and plan approval protocols.`;

const execAsync = promisify(exec);

/**
 * Valid message types
 * TypeScript: Readonly array for compile-time safety
 * Python: Set of strings
 */
const VALID_MSG_TYPES = [
    "message",
    "broadcast",
    "shutdown_request",
    "shutdown_response",
    "plan_approval_response",
] as const;

type MessageType = typeof VALID_MSG_TYPES[number];

/**
 * Teammate status enum
 * TypeScript: enum for compile-time type safety
 * Python: String literals
 */
enum TeammateStatus {
    IDLE = "idle",
    WORKING = "working",
    SHUTDOWN = "shutdown",
}

/**
 * Request status enum for protocol tracking
 * TypeScript: enum for compile-time safety
 * Python: String literals
 */
enum RequestStatus {
    PENDING = "pending",
    APPROVED = "approved",
    REJECTED = "rejected",
}

/**
 * Protocol request interface
 * TypeScript: Interface defining request structure
 * Python: Dict with keys
 */
interface ProtocolRequest {
    requestId: string;
    type: "shutdown" | "plan_approval";
    target?: string;  // For shutdown requests
    from?: string;     // For plan approval requests
    plan?: string;     // For plan approval requests
    status: RequestStatus;
    timestamp: number;
}

/**
 * Protocol response interface
 * TypeScript: Interface defining response structure
 * Python: Dict with keys
 */
interface ProtocolResponse {
    requestId: string;
    approved: boolean;
    reason?: string;
    feedback?: string;
}

/**
 * Teammate member interface
 */
interface TeammateMember {
    name: string;
    role: string;
    status: TeammateStatus;
}

/**
 * Team config interface
 */
interface TeamConfig {
    team_name: string;
    members: TeammateMember[];
}

/**
 * Message interface
 */
interface TeamMessage {
    type: MessageType;
    from: string;
    content: string;
    timestamp: number;
    [key: string]: any;
}

/**
 * MessageBus: JSONL inbox per teammate
 * TypeScript: Class with async file operations
 * Python: Class with synchronous file operations
 */
class MessageBus {
    private dir: string;

    constructor(inboxDir: string) {
        this.dir = inboxDir;
    }

    /**
     * Initialize inbox directory
     * TypeScript: Async method
     * Python: Synchronous mkdir in __init__
     */
    async init(): Promise<void> {
        await fs.mkdir(this.dir, { recursive: true });
    }

    /**
     * Send message to teammate
     * TypeScript: Async method with type validation
     * Python: Synchronous method
     */
    async send(
        sender: string,
        to: string,
        content: string,
        msgType: MessageType = "message",
        extra: Record<string, any> = {}
    ): Promise<string> {
        if (!VALID_MSG_TYPES.includes(msgType)) {
            return `Error: Invalid type '${msgType}'. Valid: ${VALID_MSG_TYPES.join(", ")}`;
        }

        const msg: TeamMessage = {
            type: msgType,
            from: sender,
            content,
            timestamp: Date.now() / 1000,
            ...extra
        };

        const inboxPath = path.join(this.dir, `${to}.jsonl`);
        const jsonLine = JSON.stringify(msg) + "\n";

        await fs.appendFile(inboxPath, jsonLine, "utf-8");
        return `Sent ${msgType} to ${to}`;
    }

    /**
     * Read and drain inbox
     * TypeScript: Async method returning Promise
     * Python: Synchronous method returning list
     */
    async readInbox(name: string): Promise<TeamMessage[]> {
        const inboxPath = path.join(this.dir, `${name}.jsonl`);

        try {
            const content = await fs.readFile(inboxPath, "utf-8");
            const lines = content.trim().split("\n");
            const messages: TeamMessage[] = [];

            for (const line of lines) {
                if (line) {
                    messages.push(JSON.parse(line));
                }
            }

            // Clear inbox after reading
            await fs.writeFile(inboxPath, "", "utf-8");

            return messages;
        } catch (error) {
            return [];
        }
    }

    /**
     * Broadcast message to all teammates except sender
     * TypeScript: Async method with array iteration
     * Python: Synchronous method
     */
    async broadcast(sender: string, content: string, teammates: string[]): Promise<string> {
        let count = 0;
        for (const name of teammates) {
            if (name !== sender) {
                await this.send(sender, name, content, "broadcast");
                count++;
            }
        }
        return `Broadcast to ${count} teammates`;
    }
}

// Initialize message bus
const BUS = new MessageBus(INBOX_DIR);

/**
 * ProtocolManager: Track and manage protocol requests
 * TypeScript: Class with encapsulated state
 * Python: Global dicts with threading.Lock()
 */
class ProtocolManager {
    private shutdownRequests: Map<string, ProtocolRequest> = new Map();
    private planRequests: Map<string, ProtocolRequest> = new Map();

    /**
     * Create shutdown request
     * TypeScript: Method returning request ID
     * Python: Function returning request ID
     */
    createShutdownRequest(target: string): string {
        const requestId = randomUUID().substring(0, 8);
        this.shutdownRequests.set(requestId, {
            requestId,
            type: "shutdown",
            target,
            status: RequestStatus.PENDING,
            timestamp: Date.now() / 1000,
        });
        return requestId;
    }

    /**
     * Create plan approval request
     * TypeScript: Method returning request ID
     * Python: Function returning request ID
     */
    createPlanRequest(from: string, plan: string): string {
        const requestId = randomUUID().substring(0, 8);
        this.planRequests.set(requestId, {
            requestId,
            type: "plan_approval",
            from,
            plan,
            status: RequestStatus.PENDING,
            timestamp: Date.now() / 1000,
        });
        return requestId;
    }

    /**
     * Update shutdown request status
     * TypeScript: Method with type safety
     * Python: Function with lock
     */
    updateShutdownStatus(requestId: string, approved: boolean): void {
        const request = this.shutdownRequests.get(requestId);
        if (request) {
            request.status = approved ? RequestStatus.APPROVED : RequestStatus.REJECTED;
        }
    }

    /**
     * Update plan request status
     * TypeScript: Method with type safety
     * Python: Function with lock
     */
    updatePlanStatus(requestId: string, approved: boolean): void {
        const request = this.planRequests.get(requestId);
        if (request) {
            request.status = approved ? RequestStatus.APPROVED : RequestStatus.REJECTED;
        }
    }

    /**
     * Get shutdown request status
     * TypeScript: Method returning request or undefined
     * Python: Function returning dict or None
     */
    getShutdownRequest(requestId: string): ProtocolRequest | undefined {
        return this.shutdownRequests.get(requestId);
    }

    /**
     * Get plan request status
     * TypeScript: Method returning request or undefined
     * Python: Function returning dict or None
     */
    getPlanRequest(requestId: string): ProtocolRequest | undefined {
        return this.planRequests.get(requestId);
    }

    /**
     * Get all pending shutdown requests
     * TypeScript: Method returning array
     * Python: List comprehension
     */
    getPendingShutdowns(): ProtocolRequest[] {
        return Array.from(this.shutdownRequests.values()).filter(
            req => req.status === RequestStatus.PENDING
        );
    }

    /**
     * Get all pending plan requests
     * TypeScript: Method returning array
     * Python: List comprehension
     */
    getPendingPlans(): ProtocolRequest[] {
        return Array.from(this.planRequests.values()).filter(
            req => req.status === RequestStatus.PENDING
        );
    }
}

// Initialize protocol manager
const PROTOCOLS = new ProtocolManager();

/**
 * TeammateManager: persistent named agents with config.json
 * TypeScript: Class with Worker management
 * Python: Class with threading.Thread management
 */
class TeammateManager {
    private dir: string;
    private configPath: string;
    private config: TeamConfig;
    private workers: Map<string, Worker> = new Map();

    constructor(teamDir: string) {
        this.dir = teamDir;
        this.configPath = path.join(teamDir, "config.json");
        this.config = { team_name: "default", members: [] };
    }

    /**
     * Initialize manager
     * TypeScript: Async initialization pattern
     * Python: Can do all initialization in __init__
     */
    async init(): Promise<void> {
        await fs.mkdir(this.dir, { recursive: true });
        await this.loadConfig();
        await BUS.init();
    }

    /**
     * Load config from file
     * TypeScript: Async method
     * Python: Synchronous method
     */
    private async loadConfig(): Promise<void> {
        try {
            const content = await fs.readFile(this.configPath, "utf-8");
            this.config = JSON.parse(content);
        } catch (error) {
            // Use default config if file doesn't exist
            this.config = { team_name: "default", members: [] };
        }
    }

    /**
     * Save config to file
     * TypeScript: Async method
     * Python: Synchronous method
     */
    private async saveConfig(): Promise<void> {
        await fs.writeFile(
            this.configPath,
            JSON.stringify(this.config, null, 2),
            "utf-8"
        );
    }

    /**
     * Find member by name
     * TypeScript: Method returning member or undefined
     * Python: Method returning member or None
     */
    private findMember(name: string): TeammateMember | undefined {
        return this.config.members.find(m => m.name === name);
    }

    /**
     * Spawn a new teammate
     * TypeScript: Creates Worker, returns immediately
     * Python: Creates Thread, returns immediately
     */
    async spawn(name: string, role: string, prompt: string): Promise<string> {
        const member = this.findMember(name);

        if (member) {
            if (member.status !== TeammateStatus.IDLE && member.status !== TeammateStatus.SHUTDOWN) {
                return `Error: '${name}' is currently ${member.status}`;
            }
            member.status = TeammateStatus.WORKING;
            member.role = role;
        } else {
            const newMember: TeammateMember = {
                name,
                role,
                status: TeammateStatus.WORKING
            };
            this.config.members.push(newMember);
        }

        await this.saveConfig();

        // Create worker for teammate
        const jsWorkerPath = path.join(__dirname, "teammate-worker.js");
        const tsWorkerPath = path.join(__dirname, "teammate-worker.ts");
        const workerPath = existsSync(jsWorkerPath) ? jsWorkerPath : tsWorkerPath;
        const worker = new Worker(workerPath, {
            workerData: {
                teammateName: name,
                role,
                prompt,
                workdir: WORKDIR,
                inboxDir: INBOX_DIR,
                modelId: MODEL,
                apiBase: process.env.ANTHROPIC_BASE_URL,
                sessionMode: "s16",
                protocolMode: "protocols",
            },
            ...(workerPath.endsWith(".ts")
                ? { execArgv: ["--loader", "ts-node/esm"] }
                : {}),
        });

        // Handle worker completion
        worker.on("message", (msg: any) => {
            if (msg.type === "teammate_complete") {
                const m = this.findMember(name);
                if (m) {
                    m.status = msg.final_status === "shutdown"
                        ? TeammateStatus.SHUTDOWN
                        : TeammateStatus.IDLE;
                    this.saveConfig();
                }
                this.workers.delete(name);
            } else if (msg.type === "tool_use") {
                console.log(`  [${msg.teammate}] ${msg.tool}: ${msg.output}`);
            }
        });

        worker.on("error", (error) => {
            console.error(`  [${name}] Worker error: ${error.message}`);
            const m = this.findMember(name);
            if (m) {
                m.status = TeammateStatus.IDLE;
                this.saveConfig();
            }
            this.workers.delete(name);
        });

        worker.on("exit", (code) => {
            if (code !== 0) {
                const m = this.findMember(name);
                if (m && m.status === TeammateStatus.WORKING) {
                    m.status = TeammateStatus.IDLE;
                    this.saveConfig();
                }
            }
            this.workers.delete(name);
        });

        this.workers.set(name, worker);

        return `Spawned '${name}' (role: ${role})`;
    }

    /**
     * List all teammates
     * TypeScript: Async method
     * Python: Synchronous method
     */
    async listAll(): Promise<string> {
        if (this.config.members.length === 0) {
            return "No teammates.";
        }

        const lines: string[] = [`Team: ${this.config.team_name}`];
        for (const m of this.config.members) {
            lines.push(`  ${m.name} (${m.role}): ${m.status}`);
        }
        return lines.join("\n");
    }

    /**
     * Get all member names
     * TypeScript: Method returning string array
     * Python: Method returning list
     */
    memberNames(): string[] {
        return this.config.members.map(m => m.name);
    }

    /**
     * Terminate all workers
     * TypeScript: Explicit cleanup required
     * Python: Daemon threads auto-clean
     */
    terminateAll(): void {
        for (const [name, worker] of Array.from(this.workers.entries())) {
            worker.terminate();
            this.workers.delete(name);
        }
    }
}

// Initialize teammate manager
const TEAMMATES = new TeammateManager(TEAM_DIR);

// -- Base tool implementations --
/**
 * Safe path resolution
 */
function safePath(p: string): string {
    const resolvedPath = path.resolve(WORKDIR, p);
    if (!resolvedPath.startsWith(WORKDIR)) {
        throw new Error(`Path escapes workspace: ${p}`);
    }
    return resolvedPath;
}

/**
 * Run bash command
 */
async function runBash(command: string): Promise<string> {
    const dangerous = ["rm -rf /", "sudo", "shutdown", "reboot", "> /dev/"];
    if (dangerous.some(d => command.includes(d))) {
        return "Error: Dangerous command blocked";
    }

    try {
        const { stdout, stderr } = await execAsync(command, {
            cwd: WORKDIR,
            timeout: 120000,
        });
        const output = (stdout + stderr).trim();
        return output ? output.substring(0, 50000) : "(no output)";
    } catch (error) {
        if ((error as any).code === "ETIMEDOUT") {
            return "Error: Timeout (120s)";
        }
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Read file contents
 */
async function runRead(filePath: string, limit?: number): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");
        const lines = content.split("\n");

        if (limit !== undefined && limit < lines.length) {
            const truncated = [
                ...lines.slice(0, limit),
                `... (${lines.length - limit} more)`
            ];
            return truncated.join("\n").substring(0, 50000);
        }

        return content.substring(0, 50000);
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Write content to file
 */
async function runWrite(filePath: string, content: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const dir = path.dirname(safeFilePath);
        await fs.mkdir(dir, { recursive: true });
        await fs.writeFile(safeFilePath, content, "utf-8");
        return `Wrote ${content.length} bytes`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Edit file by replacing exact text
 */
async function runEdit(filePath: string, oldText: string, newText: string): Promise<string> {
    try {
        const safeFilePath = safePath(filePath);
        const content = await fs.readFile(safeFilePath, "utf-8");

        if (!content.includes(oldText)) {
            return `Error: Text not found in ${filePath}`;
        }

        const updatedContent = content.replace(oldText, newText);
        await fs.writeFile(safeFilePath, updatedContent, "utf-8");
        return `Edited ${filePath}`;
    } catch (error) {
        return `Error: ${error instanceof Error ? error.message : "Unknown error"}`;
    }
}

/**
 * Handle shutdown request (lead side)
 * TypeScript: Async function using ProtocolManager
 * Python: Function using global dict and lock
 */
async function handleShutdownRequest(teammate: string): Promise<string> {
    const requestId = PROTOCOLS.createShutdownRequest(teammate);
    await BUS.send(
        "lead",
        teammate,
        "Please shut down gracefully.",
        "shutdown_request",
        { request_id: requestId }
    );
    return `Shutdown request ${requestId} sent to '${teammate}' (status: pending)`;
}

/**
 * Handle plan review (lead side)
 * TypeScript: Async function using ProtocolManager
 * Python: Function using global dict and lock
 */
async function handlePlanReview(
    requestId: string,
    approve: boolean,
    feedback: string = ""
): Promise<string> {
    const request = PROTOCOLS.getPlanRequest(requestId);
    if (!request) {
        return `Error: Unknown plan request_id '${requestId}'`;
    }

    PROTOCOLS.updatePlanStatus(requestId, approve);
    await BUS.send(
        "lead",
        request.from || "",
        feedback,
        "plan_approval_response",
        {
            request_id: requestId,
            approve: approve,
            feedback: feedback
        }
    );

    return `Plan ${approve ? "approved" : "rejected"} for '${request.from}'`;
}

